_PROD_DIRECT_SINK_REGISTRY: dict[str, dict[str, list[dict]]] = {}
_PROD_DIRECT_SINK_LOCK = threading.RLock()


def _register_production_request(prompt_id: str, request_data: dict) -> None:
    global _PROD_DIRECT_SINK_REQUESTS
    with _PROD_DIRECT_SINK_LOCK:
        data = dict(request_data)
        if "authorized_node_ids" in data and not isinstance(data["authorized_node_ids"], frozenset):
            data["authorized_node_ids"] = frozenset(str(x) for x in data["authorized_node_ids"])
        _PROD_DIRECT_SINK_REQUESTS[prompt_id] = data


def _get_production_request(prompt_id: str) -> dict | None:
    global _PROD_DIRECT_SINK_REQUESTS
    with _PROD_DIRECT_SINK_LOCK:
        return _PROD_DIRECT_SINK_REQUESTS.get(prompt_id)


def _store_production_output(prompt_id: str, node_id: str, entry: dict) -> None:
    global _PROD_DIRECT_SINK_REGISTRY
    with _PROD_DIRECT_SINK_LOCK:
        registry = _PROD_DIRECT_SINK_REGISTRY
        if prompt_id not in registry:
            registry[prompt_id] = {}
        if node_id not in registry[prompt_id]:
            registry[prompt_id][node_id] = []
        registry[prompt_id][node_id].append(entry)


def _pop_production_outputs(prompt_id: str) -> dict[str, list[dict]]:
    global _PROD_DIRECT_SINK_REGISTRY
    with _PROD_DIRECT_SINK_LOCK:
        return _PROD_DIRECT_SINK_REGISTRY.pop(prompt_id, {})


def _cleanup_production_request(prompt_id: str) -> None:
    """Remove only the request authorization entry. Output registry is cleaned by collector."""
    global _PROD_DIRECT_SINK_REQUESTS
    with _PROD_DIRECT_SINK_LOCK:
        _PROD_DIRECT_SINK_REQUESTS.pop(prompt_id, None)


def _cleanup_production_registry(prompt_id: str) -> None:
    global _PROD_DIRECT_SINK_REGISTRY
    with _PROD_DIRECT_SINK_LOCK:
        _PROD_DIRECT_SINK_REGISTRY.pop(prompt_id, None)


_PROD_DIRECT_SINK_REQUESTS: dict[str, dict] = {}


def _is_authorized_production_direct_sink_request(prompt_id: str, node_id: str) -> bool:
    req = _get_production_request(prompt_id)
    if not req or not req.get("enabled"):
        return False
    if str(req.get("prompt_id") or "") != str(prompt_id):
        return False
    authorized_node_ids = req.get("authorized_node_ids")
    if not authorized_node_ids:
        return False
    return str(node_id) in authorized_node_ids


# â”€â”€ Shared production-output encoding helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
# Module-level so both ComfyModalProductionOutput and
# ComfyModalProductionImageComparerOutput can use them.


def _encode_image_tensor_batch(images_t, output_format, quality, webp_lossless_compression):
    """Encode a single image batch tensor to bytes.

    Returns ``(entries, ext, mime_type, W, H)`` for a [B, H, W, C] uint8 tensor.
    ``entries`` is a list of ``(raw_bytes, ext, mime_type)`` tuples.
    """
    import io as _io
    from PIL import Image as _PILImage

    B, H, W, C = images_t.shape
    fmt_meta = _FORMAT_META.get(output_format, _FORMAT_META["original"])
    ext = fmt_meta["ext"]
    mime_type = fmt_meta["mime"]

    entries = []
    for batch_idx in range(B):
        arr = images_t[batch_idx].numpy()
        if output_format == "jpeg" and arr.shape[-1] == 4:
            from PIL import Image as _PILImg
            pil_img = _PILImg.fromarray(arr, mode="RGBA")
            bg = _PILImg.new("RGB", pil_img.size, (255, 255, 255))
            bg.paste(pil_img, mask=pil_img.split()[3])
            pil_img = bg
        else:
            mode = "RGBA" if arr.shape[-1] == 4 else "RGB"
            pil_img = _PILImage.fromarray(arr, mode=mode)

        out_buf = _io.BytesIO()
        if output_format == "original":
            pil_img.save(out_buf, format="PNG")
        elif output_format == "webp_lossless":
            method = _WEBP_LOSSLESS_METHOD.get(webp_lossless_compression, 4)
            pil_img.save(out_buf, format="WEBP", lossless=True, method=method)
        elif output_format == "webp_lossy":
            pil_img.save(out_buf, format="WEBP", lossless=False, quality=quality, method=_WEBP_LOSSY_METHOD)
        elif output_format == "jpeg":
            if pil_img.mode == "RGBA":
                bg = _PILImage.new("RGB", pil_img.size, (255, 255, 255))
                bg.paste(pil_img, mask=pil_img.split()[3])
                pil_img = bg
            pil_img.save(out_buf, format="JPEG", quality=quality)
        else:
            pil_img.save(out_buf, format="PNG")

        out_buf.seek(0)
        raw_bytes = out_buf.read()
        entries.append((raw_bytes, ext, mime_type))
    return entries, ext, mime_type, W, H


def _clamp_image_tensor(images):
    """Clamp and convert float32 [0,1] tensor to uint8 [0,255] on CPU.

    Handles tensors that are already uint8 or pre-scaled to [0,255] range
    gracefully by detecting the actual value range and avoiding double-scaling.
    """
    import torch
    images_t = images.detach().cpu()
    if images_t.dtype == torch.uint8:
        return images_t.contiguous()
    images_t = images_t.float()
    if float(images_t.max()) <= 1.0:
        images_t.clamp_(0.0, 1.0).mul_(255.0)
    else:
        images_t.clamp_(0.0, 255.0)
    return images_t.to(torch.uint8)


def _collect_production_request_params(req):
    """Extract output format params from production request dict."""
    output_format = req.get("output_format", "original")
    quality = int(req.get("quality", 75))
    webp_lossless_compression = req.get("webp_lossless_compression", "balanced")
    return output_format, quality, webp_lossless_compression


class ComfyModalProductionOutput:
    """Remote-only production output sink node.

    Encodes IMAGE tensors directly to the configured production format and
    stores the results in the in-memory ``_production_output_registry`` on
    the active ComfyAPI instance.

    No files are written.  Raw bytes are never placed into execution history.
    """

    CATEGORY = "_for_internal_use/ComfyModal"
    OUTPUT_NODE = True
    FUNCTION = "encode"
    RETURN_TYPES = ()

    @classmethod
    def INPUT_TYPES(cls) -> dict:
        return {
            "required": {
                "images": ("IMAGE",),
            },
            "hidden": {
                "unique_id": "UNIQUE_ID",
            },
        }

    def encode(self, images, unique_id=None):
        import time as _time

        from comfy_execution.utils import get_executing_context

        ctx = get_executing_context()
        if ctx is None:
            print("[ComfyModalProductionOutput] WARNING: no executing context, returning empty")
            return ()

        prompt_id = getattr(ctx, "prompt_id", None)
        node_id = unique_id or getattr(ctx, "node_id", None)
        if not prompt_id or not node_id:
            print("[ComfyModalProductionOutput] WARNING: missing prompt_id or node_id, returning empty")
            return ()

        # Require an active production request
        req = _get_production_request(prompt_id)
        if req is None or not req.get("enabled"):
            print(f"[ComfyModalProductionOutput] WARNING: no active production request for prompt_id={prompt_id}, returning empty")
            return ()

        # â”€â”€ Authorisation: the current prompt must match the authorised request â”€â”€
        req_prompt_id = req.get("prompt_id")
        if str(req_prompt_id) != str(prompt_id):
            print(
                f"[ComfyModalProductionOutput] WARNING: prompt_id mismatch "
                f"(request={str(req_prompt_id)[:8]!r}, executing={str(prompt_id)[:8]!r}), "
                f"returning empty"
            )
            return ()

        # â”€â”€ Authorisation: this specific node must have been rewritten by the
        #    compiler (i.e. listed in output_node_ids at production setup time).
        #    Prevents manual/user-supplied invocation of ComfyModalProductionOutput.
        authorized_ids = req.get("authorized_node_ids", [])
        if str(node_id) not in [str(a) for a in authorized_ids]:
            print(
                f"[ComfyModalProductionOutput] WARNING: node_id={node_id} not in "
                f"authorized_ids={authorized_ids}, returning empty"
            )
            return ()

        _t0 = _time.time()
        output_format, quality, webp_lossless_compression = _collect_production_request_params(req)

        try:
            from PIL import Image as _PILImage
        except ImportError:
            print("[ComfyModalProductionOutput] Pillow not available, returning empty")
            return ()

        images_t = _clamp_image_tensor(images)
        B, H, W, C = images_t.shape

        entries, ext, mime_type, W, H = _encode_image_tensor_batch(
            images_t, output_format, quality, webp_lossless_compression
        )

        prompt_id_short = str(prompt_id)[:8]
        nodestr = str(node_id)

        result_entries = []
        for batch_idx, (raw_bytes, _, _) in enumerate(entries):
            filename = f"production_{prompt_id_short}_{nodestr}_{batch_idx}{ext}"
            result_entries.append({
                "filename": filename,
                "bytes": raw_bytes,
                "mime_type": mime_type,
                "width": W,
                "height": H,
                "output_index": batch_idx,
                "node_id": node_id,
                "format": output_format,
            })

        # Store in registry
        for _entry in result_entries:
            _store_production_output(prompt_id, node_id, _entry)

        total_encode_ms = round((_time.time() - _t0) * 1000, 1)
        print(f"[ComfyModalProductionOutput] encoded {len(result_entries)} images for "
              f"prompt_id={prompt_id_short} node_id={nodestr} "
              f"format={output_format} encode_ms={total_encode_ms}")

        # Return safe success shape â€” empty tuple (no UI payload into execution
        # history).  All encoded data is already stored in the in-memory registry.
        return ()


class ComfyModalProductionImageComparerOutput:
    """Remote-only production output sink node for rgthree Image Comparer.

    Accepts ``image_a`` (required) and ``image_b`` (optional) inputs,
    encodes both sides, and stores the results in the in-memory
    production output registry with ``a_images`` and ``b_images`` keys.

    No files are written.  Raw bytes are never placed into execution history.
    """

    CATEGORY = "_for_internal_use/ComfyModal"
    OUTPUT_NODE = True
    FUNCTION = "encode_compare"
    RETURN_TYPES = ()

    @classmethod
    def INPUT_TYPES(cls) -> dict:
        return {
            "required": {
                "image_a": ("IMAGE",),
            },
            "optional": {
                "image_b": ("IMAGE",),
            },
            "hidden": {
                "unique_id": "UNIQUE_ID",
            },
        }

    def encode_compare(self, image_a, image_b=None, unique_id=None):
        import time as _time

        from comfy_execution.utils import get_executing_context

        ctx = get_executing_context()
        if ctx is None:
            print("[ComfyModalProductionImageComparerOutput] WARNING: no executing context, returning empty")
            return ()

        prompt_id = getattr(ctx, "prompt_id", None)
        node_id = unique_id or getattr(ctx, "node_id", None)
        if not prompt_id or not node_id:
            print("[ComfyModalProductionImageComparerOutput] WARNING: missing prompt_id or node_id, returning empty")
            return ()

        # Require an active production request
        req = _get_production_request(prompt_id)
        if req is None or not req.get("enabled"):
            print(f"[ComfyModalProductionImageComparerOutput] WARNING: no active production request, returning empty")
            return ()

        req_prompt_id = req.get("prompt_id")
        if str(req_prompt_id) != str(prompt_id):
            print(f"[ComfyModalProductionImageComparerOutput] WARNING: prompt_id mismatch, returning empty")
            return ()

        authorized_ids = req.get("authorized_node_ids", [])
        if str(node_id) not in [str(a) for a in authorized_ids]:
            print(f"[ComfyModalProductionImageComparerOutput] WARNING: node_id={node_id} not authorized, returning empty")
            return ()

        _t0 = _time.time()
        output_format, quality, webp_lossless_compression = _collect_production_request_params(req)
        return_a = bool(req.get("return_comparison_a", False))

        try:
            from PIL import Image as _PILImage
        except ImportError:
            print("[ComfyModalProductionImageComparerOutput] Pillow not available, returning empty")
            return ()

        prompt_id_short = str(prompt_id)[:8]
        nodestr = str(node_id)

        has_image_b = image_b is not None

        # ── Encode: B-only by default ──
        result_entries = []
        a_count = 0
        b_count = 0
        encoded_unique = 0

        if has_image_b and not return_a:
            # B-only mode: skip A, encode B only
            images_b_t = _clamp_image_tensor(image_b)
            _b_diag = f"shape={tuple(images_b_t.shape)} dtype={images_b_t.dtype}"
            print(f"[production.rgthree.encode] side=b (B-only) {_b_diag}")
            b_encoded_tensors, ext, mime_type, W, H = _encode_image_tensor_batch(
                images_b_t, output_format, quality, webp_lossless_compression
            )
            for batch_idx, (raw_bytes, _, _) in enumerate(b_encoded_tensors):
                filename = f"production_{prompt_id_short}_{nodestr}_b_{batch_idx}{ext}"
                result_entries.append({
                    "filename": filename, "bytes": raw_bytes, "mime_type": mime_type,
                    "width": W, "height": H, "output_index": batch_idx,
                    "node_id": node_id, "output_key": "b_images",
                    "comparison_side": "b", "format": output_format,
                })
                b_count += 1
            encoded_unique = b_count
        elif has_image_b:
            # return_comparison_a=True: encode A and B independently
            images_a_t = _clamp_image_tensor(image_a)
            _a_diag = f"shape={tuple(images_a_t.shape)} dtype={images_a_t.dtype}"
            print(f"[production.rgthree.encode] side=a (return-A mode) {_a_diag}")
            a_encoded_tensors, ext, mime_type, W, H = _encode_image_tensor_batch(
                images_a_t, output_format, quality, webp_lossless_compression
            )
            for batch_idx, (raw_bytes, _, _) in enumerate(a_encoded_tensors):
                filename = f"production_{prompt_id_short}_{nodestr}_a_{batch_idx}{ext}"
                result_entries.append({
                    "filename": filename, "bytes": raw_bytes, "mime_type": mime_type,
                    "width": W, "height": H, "output_index": batch_idx,
                    "node_id": node_id, "output_key": "a_images",
                    "comparison_side": "a", "format": output_format,
                })
                a_count += 1

            images_b_t = _clamp_image_tensor(image_b)
            _b_diag = f"shape={tuple(images_b_t.shape)} dtype={images_b_t.dtype}"
            print(f"[production.rgthree.encode] side=b (return-A mode) {_b_diag}")
            b_encoded_tensors, _, _, _, _ = _encode_image_tensor_batch(
                images_b_t, output_format, quality, webp_lossless_compression
            )
            for batch_idx, (raw_bytes, _, _) in enumerate(b_encoded_tensors):
                filename = f"production_{prompt_id_short}_{nodestr}_b_{batch_idx}{ext}"
                result_entries.append({
                    "filename": filename, "bytes": raw_bytes, "mime_type": mime_type,
                    "width": W, "height": H, "output_index": batch_idx,
                    "node_id": node_id, "output_key": "b_images",
                    "comparison_side": "b", "format": output_format,
                })
                b_count += 1
            encoded_unique = a_count + b_count
        else:
            # No image_b: fall back to A only
            images_a_t = _clamp_image_tensor(image_a)
            _a_diag = f"shape={tuple(images_a_t.shape)} dtype={images_a_t.dtype}"
            print(f"[production.rgthree.encode] side=a (no-B fallback) {_a_diag}")
            a_encoded_tensors, ext, mime_type, W, H = _encode_image_tensor_batch(
                images_a_t, output_format, quality, webp_lossless_compression
            )
            for batch_idx, (raw_bytes, _, _) in enumerate(a_encoded_tensors):
                filename = f"production_{prompt_id_short}_{nodestr}_a_{batch_idx}{ext}"
                result_entries.append({
                    "filename": filename, "bytes": raw_bytes, "mime_type": mime_type,
                    "width": W, "height": H, "output_index": batch_idx,
                    "node_id": node_id, "output_key": "b_images",
                    "comparison_side": "b", "format": output_format,
                })
                b_count += 1
            a_count = b_count
            encoded_unique = b_count

        # Store in registry
        for _entry in result_entries:
            _store_production_output(prompt_id, node_id, _entry)

        total_encode_ms = round((_time.time() - _t0) * 1000, 1)
        print(f"[production.rgthree] node_id={nodestr} a_count={a_count} "
              f"b_count={b_count} encoded_unique={encoded_unique} logical_outputs={len(result_entries)} "
              f"return_a={1 if return_a else 0} temp_files_written=0 encode_ms={total_encode_ms}")

        return ()




# GÃ¶Ã‡GÃ¶Ã‡ PART 2: Custom-node retry registry GÃ¶Ã‡GÃ¶Ã‡
class CustomNodeRetryEntry:
    __slots__ = (
        "path", "first_seen_at", "retry_count", "last_retry_at",
        "last_status", "last_exception_type", "last_exception_message",
        "last_traceback", "registered_delta", "retryable_reason", "resolved",
    )

    def __init__(self, path: str):
        self.path = path
        self.first_seen_at = time.time()
        self.retry_count = 0
        self.last_retry_at = 0.0
        self.last_status = "pending"
        self.last_exception_type = ""
        self.last_exception_message = ""
        self.last_traceback = ""
        self.registered_delta = 0.0
        self.retryable_reason = ""
        self.resolved = False

    def record_failure(self, exc_type: str, exc_msg: str, tb: str) -> None:
        self.last_status = "failed"
        self.last_exception_type = exc_type
        self.last_exception_message = exc_msg
        self.last_traceback = tb

    def record_retry(self) -> None:
        self.retry_count += 1
        self.last_retry_at = time.time()
        self.last_status = "retrying"

    def mark_resolved(self) -> None:
        self.resolved = True
        self.last_status = "succeeded"

    def to_dict(self) -> dict:
        return {
            "path": self.path,
            "first_seen_at": self.first_seen_at,
            "retry_count": self.retry_count,
            "last_retry_at": self.last_retry_at,
            "last_status": self.last_status,
            "last_exception_type": self.last_exception_type,
            "last_exception_message": self.last_exception_message[:500] if self.last_exception_message else "",
            "last_traceback_available": bool(self.last_traceback),
            "registered_delta": self.registered_delta,
            "retryable_reason": self.retryable_reason,
            "resolved": self.resolved,
        }


class CustomNodeRetryRegistry:
    MAX_RETRIES = 2

    def __init__(self):
        self._entries: dict[str, CustomNodeRetryEntry] = {}

    def register_failure(self, path: str, exc_type: str = "", exc_msg: str = "", tb: str = "",
                         retryable_reason: str = "") -> None:
        if path not in self._entries:
            self._entries[path] = CustomNodeRetryEntry(path)
        entry = self._entries[path]
        entry.record_failure(exc_type, exc_msg, tb)
        if retryable_reason:
            entry.retryable_reason = retryable_reason

    def should_retry(self, path: str) -> bool:
        entry = self._entries.get(path)
        if entry is None:
            return False
        if entry.resolved:
            return False
        if entry.last_status == "succeeded":
            return False
        if entry.retry_count >= self.MAX_RETRIES:
            return False
        if entry.last_exception_type == "ModuleNotFoundError" and not entry.retryable_reason:
            return False
        return True

    def record_retry(self, path: str) -> None:
        entry = self._entries.get(path)
        if entry is not None:
            entry.record_retry()

    def mark_resolved(self, path: str) -> None:
        entry = self._entries.get(path)
        if entry is not None:
            entry.mark_resolved()

    def get_entry(self, path: str) -> CustomNodeRetryEntry | None:
        return self._entries.get(path)

    def get_pending_paths(self) -> list[str]:
        return [p for p, e in self._entries.items() if e.last_status == "pending" and not e.resolved]

    def get_failed_paths(self) -> list[dict]:
        return [e.to_dict() for e in self._entries.values() if e.last_status == "failed" and not e.resolved]

    def get_all(self) -> list[dict]:
        return [e.to_dict() for e in self._entries.values()]

    def clear_resolved(self) -> None:
        self._entries = {p: e for p, e in self._entries.items() if not e.resolved}


_CUSTOM_NODE_RETRY_REGISTRY = CustomNodeRetryRegistry()

