# GÃ¶Ã‡GÃ¶Ã‡ PART 11: Known-good workflow profiles (for preload eligibility) GÃ¶Ã‡GÃ¶Ã‡
KNOWN_GOOD_WORKFLOW_PROFILES_PATH = "/root/models/runtime_config/known_good_workflow_profiles.json"
