PER_STACK_METRICS_PATH = "/root/models/runtime_config/per_stack_metrics.json"
PER_STACK_METRICS_MAX_RECORDS = 20

_WORKFLOW_IMAGE_SUFFIX_DIRS = {
    " [output]": "output",
    " [input]": "input",
    " [temp]": "temp",
}


def _split_workflow_image_reference(filename: str) -> tuple[str, str]:
    name = (filename or "").strip()
    for suffix, directory in _WORKFLOW_IMAGE_SUFFIX_DIRS.items():
        if name.endswith(suffix):
            return name[:-len(suffix)].rstrip(), directory
    return name, "input"


def _workflow_image_parts(filename: str) -> list[str]:
    normalized = (filename or "").replace("\\", "/")
    parts = [part for part in normalized.split("/") if part not in ("", ".")]
    if not parts or any(part == ".." for part in parts):
        raise ValueError(f"unsafe workflow image path: {filename}")
    return parts


def _resolve_input_image_destination(filename: str, comfy_root: str = "/root/comfy/ComfyUI") -> Path:
    relative_name, directory = _split_workflow_image_reference(filename)
    return Path(comfy_root) / directory / Path(*_workflow_image_parts(relative_name))


# Supported MIME types for experiment i2i images (mirrored from experiment_runner)
_SUPPORTED_IMAGE_MIMES = frozenset({
    "image/png", "image/jpeg", "image/webp", "image/gif", "image/bmp",
})


def _materialize_input_images(input_images: dict | None,
                               comfy_root: str = "/root/comfy/ComfyUI",
                               identity_key: tuple | None = None) -> tuple[int, int, dict]:
    """Materialize input images from base64 to disk.

    B1: *identity_key* is the 5-component tuple for per-invocation
    file tracking. When provided, files are tracked per invocation
    and cleanup only deletes that invocation's files.
    """
    import base64
    import hashlib

    input_count = 0
    input_bytes = 0
    input_hashes: set[str] = set()
    input_duplicate_hash_count = 0
    input_hash_total_ms = 0.0
    input_write_total_ms = 0.0
    for filename, value in (input_images or {}).items():
        # Support two formats:
        #   Old: {filename: b64string}
        #   New (canonical experiment): {filename: {data: b64string, ...}}
        if isinstance(value, dict) and "data" in value:
            b64data = value["data"]
            # Optional: validate MIME and hash on the remote side
            remote_mime = value.get("mime_type", "")
            if remote_mime and remote_mime not in _SUPPORTED_IMAGE_MIMES:
                raise ValueError(
                    f"Unsupported input image MIME type on remote: {remote_mime!r}. "
                    f"Supported: {', '.join(sorted(_SUPPORTED_IMAGE_MIMES))}"
                )
        elif isinstance(value, str):
            b64data = value
        else:
            continue  # skip unparseable entries

        dest = _resolve_input_image_destination(filename, comfy_root=comfy_root)
        dest.parent.mkdir(parents=True, exist_ok=True)
        _t_hash = time.time()
        raw = base64.b64decode(b64data)
        _digest = hashlib.sha256(raw).hexdigest()
        _hash_ms = round((time.time() - _t_hash) * 1000, 1)
        input_hash_total_ms += _hash_ms
        if _digest in input_hashes:
            input_duplicate_hash_count += 1
        else:
            input_hashes.add(_digest)
        _t_write = time.time()
        dest.write_bytes(raw)
        _write_ms = round((time.time() - _t_write) * 1000, 1)
        input_write_total_ms += _write_ms
        input_count += 1
        input_bytes += len(raw)
        # B1: Track materialized files per invocation identity
        _track_materialized_file(str(dest), identity_key=identity_key)
    telemetry = {
        "input_materialize_count": input_count,
        "input_materialize_total_bytes": input_bytes,
        "input_materialize_duplicate_hash_count": input_duplicate_hash_count,
        "input_materialize_unique_hash_count": len(input_hashes),
        "input_materialize_hash_ms": round(input_hash_total_ms, 1),
        "input_materialize_write_ms": round(input_write_total_ms, 1),
    }
    return input_count, input_bytes, telemetry


# ── Input image cleanup tracking ─────────────────────────────────────────
# Used by the experiment checkpoint stream to defer cleanup until all
# cells in a checkpoint have finished, preventing one cell from deleting
# a file another cell still needs.
#
# B1: Per-invocation i2i ownership.  Instead of a process-global list,
# materialized files are tracked per 5-component identity tuple:
#   (deployment_generation, experiment_id, checkpoint_id,
#    worker_invocation_id, lease_generation)
# Each invocation writes only its own files; cleanup deletes only its own files.

_MATERIALIZED_FILES: list[str] = []  # legacy global list (pre-B1)
_MATERIALIZED_FILES_BY_INVOCATION: dict[tuple, list[str]] = {}
_INVOCATION_IDENTITY_SENTINEL = "__default__"


def _build_invocation_key(deployment_generation: str = "",
                          experiment_id: str = "",
                          checkpoint_id: str = "",
                          worker_invocation_id: str = "",
                          lease_generation: int = 0) -> tuple:
    """Build a 5-component identity key for per-invocation file tracking."""
    return (deployment_generation, experiment_id, checkpoint_id,
            worker_invocation_id, lease_generation)


def _track_materialized_file(path_str: str,
                              identity_key: tuple | None = None) -> None:
    """Record a materialized file path for later cleanup.

    When *identity_key* is provided, the path is tracked per-invocation.
    When None (legacy path), falls back to the process-global list.
    """
    if identity_key is not None:
        files = _MATERIALIZED_FILES_BY_INVOCATION.setdefault(identity_key, [])
        if path_str not in files:
            files.append(path_str)
    else:
        if path_str not in _MATERIALIZED_FILES:
            _MATERIALIZED_FILES.append(path_str)


def _cleanup_all_materialized_files(identity_key: tuple | None = None) -> int:
    """Delete all tracked materialized files for the given identity key.

    B1: When *identity_key* is provided, only files for that invocation
    are deleted and the per-invocation entry is removed.
    When None (legacy call), the global list is used.

    Returns the number of files deleted.
    """
    deleted = 0
    seen: set[str] = set()
    if identity_key is not None:
        files = _MATERIALIZED_FILES_BY_INVOCATION.pop(identity_key, [])
        for path_str in files:
            if path_str in seen:
                continue
            seen.add(path_str)
            try:
                p = Path(path_str)
                if p.exists():
                    p.unlink()
                    deleted += 1
            except Exception:
                pass
    else:
        for path_str in list(_MATERIALIZED_FILES):
            if path_str in seen:
                continue
            seen.add(path_str)
            try:
                p = Path(path_str)
                if p.exists():
                    p.unlink()
                    deleted += 1
            except Exception:
                pass
        _MATERIALIZED_FILES.clear()
    return deleted


def _model_cpu_cache_key(path: str) -> str:
    normalized = os.path.realpath(path) if path else path
    return os.path.normcase(os.path.normpath(normalized))


def _model_cpu_cache_lookup_keys(path: str) -> tuple[str, ...]:
    full_key = _model_cpu_cache_key(path)
    raw_norm = os.path.normcase(os.path.normpath(path)) if path else path
    basename = os.path.basename(path)
    candidates = []
    for candidate in (full_key, raw_norm, path, basename):
        if candidate and candidate not in candidates:
            candidates.append(candidate)
    return tuple(candidates)


def load_safetensors_cpu_with_mode(path, *, device="cpu", read_mode="auto",
                                    model_role="", loader_name="") -> tuple:
    """Load a safetensors file with configurable read strategy.

    Returns (state_dict, metadata) matching comfy.utils.load_torch_file.
    Falls back to original loader on exception unless SAFETENSORS_STRICT=1.
    """
    _t_total = time.time()
    _diag = {
        "safetensors_read_mode": "normal",
        "model_role": model_role,
        "loader_name": loader_name,
        "file_size_gb": 0.0,
        "read_bytes_ms": 0.0,
        "decode_ms": 0.0,
        "total_load_ms": 0.0,
        "fallback_reason": "",
        "peak_extra_ram_estimate_gb": 0.0,
    }
    _read_mode = read_mode if read_mode in ("auto", "normal", "read_bytes") else "normal"
    _file_ext = os.path.splitext(path)[1].lower()
    _file_size = 0
    try:
        _file_size = os.path.getsize(path)
    except OSError:
        pass
    _file_size_gb = round(_file_size / (1024**3), 3)
    _diag["file_size_gb"] = _file_size_gb

    _use_read_bytes = False
    if _read_mode == "read_bytes":
        _use_read_bytes = True
    elif _read_mode == "auto":
        _on_model_path = ("/root/models" in path or "/root/comfy/ComfyUI/models" in path)
        _is_safetensors = _file_ext == ".safetensors"
        _above_threshold = (_file_size / (1024 * 1024)) >= SAFETENSORS_READ_BYTES_MIN_MB
        _is_cpu = device == "cpu"
        if _is_cpu and _is_safetensors and _above_threshold and _on_model_path:
            _use_read_bytes = True

    if not _use_read_bytes:
        _diag["total_load_ms"] = round((time.time() - _t_total) * 1000, 1)
        return None, _diag

    try:
        _tr = time.time()
        _raw = open(path, "rb").read()
        _diag["read_bytes_ms"] = round((time.time() - _tr) * 1000, 1)
        _diag["peak_extra_ram_estimate_gb"] = round(len(_raw) / (1024**3), 3)
        _diag["safetensors_read_mode"] = "read_bytes"

        import safetensors.torch as _st
        _td = time.time()
        _result = _st.load(_raw)
        _diag["decode_ms"] = round((time.time() - _td) * 1000, 1)
        _diag["total_load_ms"] = round((time.time() - _t_total) * 1000, 1)

        _sd = _result.get("__metadata__", {})
        _tensors = {k: v for k, v in _result.items() if k != "__metadata__"}
        return ({"state_dict": _tensors, "metadata": _sd}, _diag)

    except Exception as _exc:
        _diag["fallback_reason"] = f"{_exc}"[:200]
        _diag["safetensors_read_mode"] = "fallback"
        _diag["total_load_ms"] = round((time.time() - _t_total) * 1000, 1)
        if SAFETENSORS_STRICT:
            raise
        print(f"[safetensors] read_bytes fallback to normal for {os.path.basename(path)}: {_exc}")
        return None, _diag


_SCOPED_SAFETENSORS_LOCK = threading.Lock()
_SCOPED_SAFETENSORS_ORIGINAL_LOAD_FILE = None
_SCOPED_SAFETENSORS_DEPTH = 0


@contextlib.contextmanager
def scoped_safetensors_read_mode(read_mode="auto", model_role="", loader_name=""):
    """Context manager that temporarily patches safetensors.torch.load_file.

    Only patches during the with-block. Restores original on exit.
    Thread-safe via _SCOPED_SAFETENSORS_LOCK. Does not nest safely with
    concurrent scoped patches.
    """
    global _SCOPED_SAFETENSORS_ORIGINAL_LOAD_FILE, _SCOPED_SAFETENSORS_DEPTH
    import safetensors.torch as _st

    with _SCOPED_SAFETENSORS_LOCK:
        _SCOPED_SAFETENSORS_DEPTH += 1
        if _SCOPED_SAFETENSORS_ORIGINAL_LOAD_FILE is None:
            _SCOPED_SAFETENSORS_ORIGINAL_LOAD_FILE = _st.load_file

        def _patched_load_file(filename, device="cpu"):
            _result, _diag = load_safetensors_cpu_with_mode(
                filename, device=device, read_mode=read_mode,
                model_role=model_role, loader_name=loader_name,
            )
            if _result is not None:
                return _result[0]["state_dict"]
            return _SCOPED_SAFETENSORS_ORIGINAL_LOAD_FILE(filename, device=device)

        _st.load_file = _patched_load_file

    try:
        yield
    finally:
        with _SCOPED_SAFETENSORS_LOCK:
            if _SCOPED_SAFETENSORS_ORIGINAL_LOAD_FILE is not None:
                _st.load_file = _SCOPED_SAFETENSORS_ORIGINAL_LOAD_FILE
            _SCOPED_SAFETENSORS_DEPTH -= 1
            if _SCOPED_SAFETENSORS_DEPTH <= 0:
                _SCOPED_SAFETENSORS_ORIGINAL_LOAD_FILE = None
                _SCOPED_SAFETENSORS_DEPTH = 0


def _iter_image_entries(node_out: dict):
    """Yield ``(output_key, entry)`` for each entry in ``node_out`` that looks
    like an image/video file reference (dict with a ``"filename"`` key).

    Skips non-list values (e.g. ``"animated"``).  The caller still needs to
    check ``node_out.get("animated", False)`` for the per-node animation flag.
    """
    for key, value in node_out.items():
        if not isinstance(value, list):
            continue
        for entry in value:
            if isinstance(entry, dict) and "filename" in entry:
                yield key, entry


def _apply_return_mode(result: dict, return_mode: str, payload_image_count: int, payload_video_count: int) -> dict:
    result.setdefault("_return_payload_info", {})["return_mode"] = return_mode
    if return_mode == "first_image_only" and result.get("images"):
        result["images"] = result["images"][:1]
        new_b64 = sum(len(img.get("data", "")) for img in result["images"])
        result["_return_payload_info"]["b64_bytes"] = new_b64
        print(f"[comfyapp] return_mode=first_image_only: kept 1/{payload_image_count} images, b64={new_b64}")
    elif return_mode == "metadata_only":
        for img in result.get("images", []):
            img.pop("data", None)
        for vid in result.get("videos", []):
            vid.pop("data", None)
        result["_return_payload_info"]["b64_bytes"] = 0
        print(f"[comfyapp] return_mode=metadata_only: stripped data from {payload_image_count} images/{payload_video_count} videos")
    elif return_mode == "paths_only":
        for img in result.get("images", []):
            img.pop("data", None)
            img["path"] = f"/root/comfy/ComfyUI/output/{img.get('filename', '')}"
        for vid in result.get("videos", []):
            vid.pop("data", None)
            vid["path"] = f"/root/comfy/ComfyUI/output/{vid.get('filename', '')}"
        result["_return_payload_info"]["b64_bytes"] = 0
        print(f"[comfyapp] return_mode=paths_only: {payload_image_count} images, {payload_video_count} videos")
    return result


def _resolve_runtime_flag(name: str, default: str) -> bool:
    """Read a runtime ``0``/``1`` flag from file or env var.

    Priority:
    1. File on the model volume at ``runtime_config/{name}.txt``.
    2. Env var ``COMFYMODAL_{name}``.
    3. ``default`` string (``"0"`` or ``"1"``).
    """
    path = os.path.join(RUNTIME_CONFIG_DIR, f"{name}.txt")
    try:
        if os.path.isfile(path):
            v = open(path).read().strip().lower()
            if v in ("0", "1"):
                return v == "1"
    except Exception:
        pass
    env = os.environ.get(f"COMFYMODAL_{name}", default)
    return env == "1"


def _resolve_runtime_string(name: str, default: str, allowed: set[str] | tuple[str, ...] | None = None) -> str:
    """Read a runtime string flag from file or env var.

    Priority:
    1. File on the model volume at ``runtime_config/{name}.txt``.
    2. Env var ``COMFYMODAL_{name}``.
    3. ``default`` string.

    When *allowed* is provided, the value is validated against the set.
    Returns *default* if an invalid value is encountered.
    """
    path = os.path.join(RUNTIME_CONFIG_DIR, f"{name}.txt")
    try:
        if os.path.isfile(path):
            v = open(path).read().strip().lower()
            if v and (allowed is None or v in allowed):
                return v
    except Exception:
        pass
    env = os.environ.get(f"COMFYMODAL_{name}", default).strip().lower()
    if allowed is not None and env not in allowed:
        return default
    return env


def _resolve_restore_direct_clip_policy_name() -> str:
    """Return the effective RESTORE_DIRECT_CLIP_POLICY from runtime or module default.

    Priority:
    1. File ``runtime_config/RESTORE_DIRECT_CLIP_POLICY.txt``.
    2. Env var ``COMFYMODAL_RESTORE_DIRECT_CLIP_POLICY``.
    3. Module-level ``RESTORE_DIRECT_CLIP_POLICY``.
    """
    return _resolve_runtime_string(
        "RESTORE_DIRECT_CLIP_POLICY",
        RESTORE_DIRECT_CLIP_POLICY,
        allowed={"auto", "off", "load_only", "load_and_encode"},
    )


def _resolve_sage_runtime_env_override() -> str:
    """Return the effective SAGE_RUNTIME_MODE from file, env, or module default.

    Priority:
    1. File ``runtime_config/sage_runtime_mode.txt``.
    2. Module-level ``SAGE_RUNTIME_MODE`` (from env var ``COMFYMODAL_SAGE_RUNTIME_MODE``).
    """
    path = os.path.join(RUNTIME_CONFIG_DIR, "sage_runtime_mode.txt")
    try:
        if os.path.isfile(path):
            v = open(path).read().strip().lower()
            if v in ("auto", "baked_cuda", "triton_fallback"):
                return v
    except Exception:
        pass
    return SAGE_RUNTIME_MODE


def _resolve_sage_probe_on_restore() -> bool:
    """Return whether to probe Sage runtime during restore.

    Priority:
    1. File ``runtime_config/sage_runtime_probe.txt``.
    2. Module-level ``SAGE_RUNTIME_PROBE_ON_RESTORE``.
    """
    path = os.path.join(RUNTIME_CONFIG_DIR, "sage_runtime_probe.txt")
    try:
        if os.path.isfile(path):
            v = open(path).read().strip().lower()
            if v in ("0", "1"):
                return v == "1"
    except Exception:
        pass
    return SAGE_RUNTIME_PROBE_ON_RESTORE


def _resolve_preload_mode() -> str:
    """Return the effective preload mode.

    Priority:
    1. File on the model volume (set by ``set_preload_mode``).
    2. Module-level env-var default (``PRELOAD_MODE``).
    """
    try:
        if os.path.isfile(PRELOAD_MODE_PATH):
            _v = open(PRELOAD_MODE_PATH).read().strip().lower()
            if _v:
                return _v
    except Exception:
        pass
    return PRELOAD_MODE


def _resolve_return_mode() -> str:
    """Return the effective return mode.

    Priority:
    1. File on the model volume (set by ``set_return_mode``).
    2. Env var ``COMFYMODAL_RETURN_MODE``.
    3. ``"full_base64"`` (default).
    """
    try:
        if os.path.isfile(RUNTIME_RETURN_MODE_PATH):
            _v = open(RUNTIME_RETURN_MODE_PATH).read().strip().lower()
            if _v in ("full_base64", "first_image_only", "metadata_only", "paths_only", "urls_only"):
                return _v
    except Exception:
        pass
    _valid = ("full_base64", "first_image_only", "metadata_only", "paths_only", "urls_only")
    _env = os.environ.get("COMFYMODAL_RETURN_MODE", "").strip().lower()
    if _env in _valid:
        return _env
    return "full_base64"


def _resolve_restore_direct_clip_policy(profile: dict | None, has_active_prompt_overlap: bool = False) -> dict:
    """Resolve the restore direct CLIP policy to a specific decision.

    Returns a dict with:
      policy, decision, load_clip_effective, clip_encode_effective, skip_reason
    """
    _policy = _resolve_restore_direct_clip_policy_name()
    _decision = ""
    _load_clip = 0
    _encode = 0
    _skip_reason = ""

    _clip_name = (profile or {}).get("clip1", "")
    _has_clip_in_profile = bool(_clip_name)

    if _policy == "off":
        _decision = "off_explicit"
        return {
            "restore_direct_clip_policy": _policy,
            "restore_direct_clip_policy_decision": _decision,
            "direct_warmup_load_clip_effective": 0,
            "direct_warmup_clip_encode_effective": 0,
            "direct_warmup_clip_skip_reason": "off_explicit",
        }

    if _policy == "load_only":
        _decision = "load_only_explicit"
        return {
            "restore_direct_clip_policy": _policy,
            "restore_direct_clip_policy_decision": _decision,
            "direct_warmup_load_clip_effective": 1 if _has_clip_in_profile else 0,
            "direct_warmup_clip_encode_effective": 0,
            "direct_warmup_clip_skip_reason": "load_only_explicit",
        }

    if _policy == "load_and_encode":
        _decision = "load_and_encode_explicit"
        return {
            "restore_direct_clip_policy": _policy,
            "restore_direct_clip_policy_decision": _decision,
            "direct_warmup_load_clip_effective": 1 if _has_clip_in_profile else 0,
            "direct_warmup_clip_encode_effective": 1 if _has_clip_in_profile else 0,
            "direct_warmup_clip_skip_reason": "",
        }

    if _policy == "auto":
        if not _has_clip_in_profile:
            _decision = "skipped_no_clip_in_profile"
            _skip_reason = "no_clip_in_profile"
        elif has_active_prompt_overlap:
            _decision = "load_and_encode_default"
        else:
            _decision = "load_and_encode_default"

        _load_clip = 1 if _has_clip_in_profile else 0
        _encode = _load_clip

        return {
            "restore_direct_clip_policy": _policy,
            "restore_direct_clip_policy_decision": _decision,
            "direct_warmup_load_clip_effective": _load_clip,
            "direct_warmup_clip_encode_effective": _encode,
            "direct_warmup_clip_skip_reason": _skip_reason,
        }

    return {
        "restore_direct_clip_policy": _policy,
        "restore_direct_clip_policy_decision": "fallback_existing",
        "direct_warmup_load_clip_effective": 0,
        "direct_warmup_clip_encode_effective": 0,
        "direct_warmup_clip_skip_reason": "fallback_existing",
    }

# GÃ¶Ã‡GÃ¶Ã‡ Custom-node volume helpers GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡

def _safe_listdir(path: str) -> list[str]:
    if not os.path.isdir(path):
        return []
    return sorted(os.listdir(path))


def custom_node_source_fingerprint(source_root: str) -> dict:
    """Return a fingerprint of the top-level custom-node directory structure
    including file content hashes (not just topology)."""
    nodes = []
    for name in _iter_syncable_custom_node_dirs(source_root):
        node_path = os.path.join(source_root, name)
        entry = {"name": name, "is_dir": True}
        if os.path.islink(node_path):
            entry["realpath_if_symlink"] = os.path.realpath(node_path)
        _hasher = hashlib.sha256()
        _tracked_exts = {".py", ".txt", ".toml", ".cfg"}
        _tracked_files = {"requirements.txt", "pyproject.toml", "setup.py", "setup.cfg"}
        try:
            for _dirpath, _dirnames, _filenames in os.walk(node_path):
                _dirnames[:] = [d for d in _dirnames if d not in (".git", "__pycache__", "node_modules", ".venv", "venv")]
                for _fn in sorted(_filenames):
                    _ext = os.path.splitext(_fn)[1].lower()
                    if _ext in _tracked_exts or _fn in _tracked_files:
                        _fp = os.path.join(_dirpath, _fn)
                        _rel = os.path.relpath(_fp, node_path).replace("\\", "/")
                        _hasher.update(f"{_rel}:".encode())
                        try:
                            _hasher.update(Path(_fp).read_bytes())
                        except OSError:
                            pass
        except Exception:
            pass
        entry["content_hash"] = _hasher.hexdigest()[:16]
        nodes.append(entry)
    return {
        "schema_version": 2,
        "source_root": source_root,
        "nodes": nodes,
    }


# Alias for backward compatibility
custom_node_topology_fingerprint = custom_node_source_fingerprint


def _is_volume_managed_link(link_path: str, volume_root: str) -> bool:
    if not os.path.islink(link_path):
        return False
    target = os.path.realpath(link_path)
    try:
        common = os.path.commonpath([os.path.abspath(volume_root), os.path.abspath(target)])
    except ValueError:
        return False
    return common == os.path.abspath(volume_root)


def custom_node_volume_state(volume_root: str) -> tuple:
    volume_root = os.path.abspath(volume_root)
    state = []
    for name in _iter_syncable_custom_node_dirs(volume_root):
        path = os.path.join(volume_root, name)
        stat = os.stat(path)
        req_file = os.path.join(path, "requirements.txt")
        req_mtime_ns = os.stat(req_file).st_mtime_ns if os.path.isfile(req_file) else None
        state.append((name, stat.st_mtime_ns, req_mtime_ns))
    return tuple(state)


def missing_expected_nodes(state: tuple, expected_nodes: list[str]) -> list[str]:
    visible = {name for name, *_ in state}
    return [name for name in expected_nodes if name not in visible]


def sync_custom_nodes_into_comfy(volume_root: str, comfy_custom_nodes_root: str, include_state: bool = False) -> dict:
    volume_root = os.path.abspath(volume_root)
    comfy_custom_nodes_root = os.path.abspath(comfy_custom_nodes_root)
    os.makedirs(comfy_custom_nodes_root, exist_ok=True)

    volume_dirs = []
    state = []
    for name in _iter_syncable_custom_node_dirs(volume_root):
        path = os.path.join(volume_root, name)
        volume_dirs.append(name)
        if include_state:
            stat = os.stat(path)
            req_file = os.path.join(path, "requirements.txt")
            req_mtime_ns = os.stat(req_file).st_mtime_ns if os.path.isfile(req_file) else None
            state.append((name, stat.st_mtime_ns, req_mtime_ns))

    removed = []
    created = []
    kept = []
    blocked = []

    for name in _safe_listdir(comfy_custom_nodes_root):
        dst = os.path.join(comfy_custom_nodes_root, name)
        if not _is_volume_managed_link(dst, volume_root):
            continue
        expected_src = os.path.join(volume_root, name)
        if name not in volume_dirs or os.path.realpath(dst) != os.path.realpath(expected_src):
            os.unlink(dst)
            removed.append(name)

    for name in sorted(volume_dirs):
        src = os.path.join(volume_root, name)
        dst = os.path.join(comfy_custom_nodes_root, name)
        if os.path.islink(dst) and os.path.realpath(dst) == os.path.realpath(src):
            kept.append(name)
            continue
        if os.path.lexists(dst):
            # A real directory (not a volume-managed symlink) is blocking
            # the symlink.  The volume is the source of truth for custom
            # nodes, so remove the directory and replace it with a symlink.
            # This handles the case where a previous image or snapshot
            # installed the node as a real directory.
            if os.path.isdir(dst) and not os.path.islink(dst):
                import shutil
                shutil.rmtree(dst)
                print(f"[comfyapp] sync: replaced real directory with volume symlink name={name}")
            else:
                os.unlink(dst)
        os.symlink(src, dst)
        created.append(name)

    result = {
        "created": created,
        "removed": removed,
        "kept": kept,
        "blocked": blocked,
    }
    if include_state:
        result["state"] = tuple(state)
    print(f"[comfyapp] sync_custom_nodes_into_comfy: created={len(created)} kept={len(kept)} "
          f"removed={len(removed)} blocked={len(blocked)} volume_dirs={len(volume_dirs)}")
    return result

RUNTIME_METADATA_PATH = "/root/models/runtime_config/runtime_metadata.json"


def requirements_file_hash(path: str) -> str | None:
    """Return sha256 hex of a requirements.txt file, or None if missing."""
    if not os.path.isfile(path):
        return None
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def collect_custom_node_dependency_files(node_path: str) -> dict[str, str]:
    """Collect dependency-relevant file paths under *node_path*.

    This is the single source of truth for dependency file scanning.
    Used by both ``build_custom_node_dependency_manifest`` (hashing)
    and ``_prepare_custom_node_requirements_build_context`` (copying).

    Returns a dict of ``relative_path -> sha256_hex`` for:
    - requirements.txt
    - any file included by -r / --requirement
    - pyproject.toml, setup.py, setup.cfg
    - local wheel files referenced by requirements
    - local packages/folders referenced by -e, --editable, ./path, ../path
    - constraints files included by -c / --constraint

    Does NOT hash the whole source tree.  Ignores .git, __pycache__,
    node_modules, venv, .venv, image files, videos, markdown docs,
    notebooks, model files.
    """
    _IGNORE_EXTS = {".jpg", ".jpeg", ".png", ".gif", ".tiff", ".bmp",
                    ".webp", ".ico", ".mp4", ".avi", ".mov", ".mkv",
                    ".webm", ".md", ".rst", ".ipynb", ".gz", ".zip",
                    ".tar", ".pyc", ".pyo", ".safetensors", ".ckpt",
                    ".pt", ".pth", ".bin"}
    _IGNORE_DIRS = {".git", "__pycache__", "node_modules", ".venv", "venv",
                    ".ipynb_checkpoints"}

    files: dict[str, str] = {}
    _seen_real: set[str] = set()

    def _add_file(filepath: str, node_root: str) -> None:
        if not os.path.isfile(filepath):
            return
        real = os.path.realpath(filepath)
        if real in _seen_real:
            return
        _seen_real.add(real)
        rel = _safe_dependency_relpath(filepath, node_root)
        files[rel] = hashlib.sha256(Path(filepath).read_bytes()).hexdigest()

    def _scan_requirements(req_path: str, node_root: str, seen_req: set[str]) -> None:
        req_path = os.path.abspath(req_path)
        if req_path in seen_req:
            return
        seen_req.add(req_path)
        if not os.path.isfile(req_path):
            return
        _add_file(req_path, node_root)
        req_dir = os.path.dirname(req_path)
        try:
            for line in Path(req_path).read_text(encoding="utf-8").splitlines():
                stripped = line.strip()
                if not stripped or stripped.startswith("#"):
                    continue
                stripped = stripped.split(";", 1)[0].strip()
                if not stripped:
                    continue
                if stripped.startswith("-r ") or stripped.startswith("--requirement "):
                    prefix = stripped.split(" ", 1)[1].strip()
                    included = os.path.abspath(os.path.join(req_dir, prefix))
                    if os.path.isfile(included):
                        _scan_requirements(included, node_root, seen_req)
                elif stripped.startswith("-c ") or stripped.startswith("--constraint "):
                    prefix = stripped.split(" ", 1)[1].strip()
                    included = os.path.abspath(os.path.join(req_dir, prefix))
                    _add_file(included, node_root)
                elif stripped.startswith("-e ") or stripped.startswith("--editable "):
                    local_path = stripped.split(" ", 1)[1].strip()
                    resolved = os.path.abspath(os.path.join(req_dir, local_path))
                    _add_tree(resolved, node_root)
                elif stripped.startswith("./") or stripped.startswith("../"):
                    local_path = os.path.abspath(os.path.join(req_dir, stripped))
                    _add_tree(local_path, node_root)
        except (OSError, UnicodeDecodeError):
            pass

    def _add_tree(path: str, node_root: str) -> None:
        if not os.path.exists(path):
            return
        real = os.path.realpath(path)
        if real in _seen_real:
            return
        _seen_real.add(real)
        if os.path.isfile(path):
            rel = _safe_dependency_relpath(path, node_root)
            files[rel] = hashlib.sha256(Path(path).read_bytes()).hexdigest()
        elif os.path.isdir(path):
            for dirpath, dirnames, filenames in os.walk(path):
                dirnames[:] = [d for d in dirnames if d not in _IGNORE_DIRS]
                for fn in filenames:
                    ext = os.path.splitext(fn)[1].lower()
                    if ext in _IGNORE_EXTS:
                        continue
                    fp = os.path.join(dirpath, fn)
                    _add_file(fp, node_root)

    req_path = os.path.join(node_path, "requirements.txt")
    _scan_requirements(req_path, node_path, set())

    req_dir = os.path.join(node_path, "requirements")
    if os.path.isdir(req_dir):
        for _rf in sorted(os.listdir(req_dir)):
            if _rf.endswith(".txt") or _rf.endswith(".pip"):
                _scan_requirements(os.path.join(req_dir, _rf), node_path, set())

    for base_name in ("pyproject.toml", "setup.py", "setup.cfg", "install.py"):
        base_path = os.path.join(node_path, base_name)
        if os.path.isfile(base_path):
            _add_file(base_path, node_path)

    return files


def _collect_dependency_file_paths(node_path: str) -> dict[str, str]:
    """Backward-compatible alias for ``collect_custom_node_dependency_files``."""
    return collect_custom_node_dependency_files(node_path)


class RequestPipelineState:
    """Structured request pipeline state for truthful summary generation.

    Tracks every phase of a prompt request through the pipeline so the
    summary dict is populated from real state rather than best-effort kwargs.
    """

    __slots__ = (
        "request_id", "mode", "stream",
        "workflow_hash", "model_stack",
        "local_preflight_validated", "remote_preflight_validated",
        "custom_node_sync_result", "custom_node_sync_skipped",
        "custom_node_sync_skip_reason",
        "dependency_result", "dependency_manifest_cache_hit",
        "missing_node_result",
        "active_profile_result", "active_profile_expired",
        "active_profile_source", "preload_skip_reason",
        "prompt_preload_result", "actual_load_result",
        "execution_started", "execution_success",
        "known_good_marked", "known_good_mark_result",
        "failure_phase", "failure_reason",
        "clip_actual_load_submitted", "clip_actual_load_cache_hit",
        "clip_actual_load_duration_ms",
        "_timestamps",
    )

    def __init__(self, request_id: str = "", mode: str = "", stream: bool = False):
        self.request_id = request_id
        self.mode = mode
        self.stream = stream
        self.workflow_hash = ""
        self.model_stack = {}
        self.local_preflight_validated = False
        self.remote_preflight_validated = False
        self.custom_node_sync_result = ""
        self.custom_node_sync_skipped = False
        self.custom_node_sync_skip_reason = ""
        self.dependency_result = ""
        self.dependency_manifest_cache_hit = False
        self.missing_node_result = ""
        self.active_profile_result = ""
        self.active_profile_expired = False
        self.active_profile_source = ""
        self.preload_skip_reason = ""
        self.prompt_preload_result = ""
        self.actual_load_result = ""
        self.execution_started = False
        self.execution_success = False
        self.known_good_marked = False
        self.known_good_mark_result = ""
        self.failure_phase = ""
        self.failure_reason = ""
        self.clip_actual_load_submitted = False
        self.clip_actual_load_cache_hit = False
        self.clip_actual_load_duration_ms = 0.0
        self._timestamps: dict[str, float] = {}

    def mark(self, phase: str) -> None:
        self._timestamps[phase] = time.time()

    def fail(self, phase: str, reason: str) -> None:
        self.failure_phase = phase
        self.failure_reason = reason
        self.mark(f"fail_{phase}")

    def to_summary(self) -> dict:
        return {
            "request_id": self.request_id,
            "mode": self.mode,
            "stream": self.stream,
            "workflow_hash": self.workflow_hash,
            "model_stack": self.model_stack,
            "local_preflight_validated": self.local_preflight_validated,
            "remote_preflight_validated": self.remote_preflight_validated,
            "custom_node_sync_result": self.custom_node_sync_result,
            "custom_node_sync_skipped": self.custom_node_sync_skipped,
            "custom_node_sync_skip_reason": self.custom_node_sync_skip_reason,
            "dependency_result": self.dependency_result,
            "dependency_manifest_cache_hit": self.dependency_manifest_cache_hit,
            "missing_node_result": self.missing_node_result,
            "active_profile_result": self.active_profile_result,
            "active_profile_expired": self.active_profile_expired,
            "active_profile_source": self.active_profile_source,
            "preload_skip_reason": self.preload_skip_reason,
            "prompt_preload_result": self.prompt_preload_result,
            "actual_load_result": self.actual_load_result,
            "execution_started": self.execution_started,
            "execution_success": self.execution_success,
            "known_good_marked": self.known_good_marked,
            "known_good_mark_result": self.known_good_mark_result,
            "failure_phase": self.failure_phase,
            "failure_reason": self.failure_reason,
            "clip_actual_load_submitted": self.clip_actual_load_submitted,
            "clip_actual_load_cache_hit": self.clip_actual_load_cache_hit,
            "clip_actual_load_duration_ms": self.clip_actual_load_duration_ms,
        }


def make_request_pipeline_summary(**kwargs) -> dict:
    """Build a compact request pipeline summary for log/metadata.

    Passes all kwargs matching ``RequestPipelineState`` fields through
    to the state object so callers provide real data rather than defaults.
    """
    state = RequestPipelineState(
        request_id=kwargs.get("request_id", ""),
        mode=kwargs.get("mode", ""),
        stream=kwargs.get("stream", False),
    )
    for field in RequestPipelineState.__slots__:
        if field in kwargs and field not in ("request_id", "mode", "stream"):
            setattr(state, field, kwargs[field])
    return state.to_summary()


def custom_node_dependency_fingerprint(source_root: str) -> dict:
    """Build a dependency-only fingerprint for caching.

    Uses ``collect_custom_node_dependency_files`` for every top-level
    custom node.  Includes only dependency-relevant files (no ordinary
    .py source, no mtimes).  The ``overall_dependency_hash`` changes
    only when dependency-relevant files change.

    Returns:
        ``{"schema_version": 1, "source_root": str, "nodes": {...},
          "overall_dependency_hash": str}``
    """
    hasher = hashlib.sha256()
    nodes_out: dict = {}
    for entry in _iter_syncable_custom_node_dirs(source_root):
        node_path = os.path.join(source_root, entry)
        dep_files = collect_custom_node_dependency_files(node_path)
        if not dep_files:
            continue
        nodes_out[entry] = {"dependency_files": dep_files}
        for rel_path in sorted(dep_files):
            hasher.update(f"{entry}/{rel_path}:{dep_files[rel_path]}".encode())

    return {
        "schema_version": 1,
        "source_root": source_root,
        "nodes": nodes_out,
        "overall_dependency_hash": hasher.hexdigest(),
    }


def build_custom_node_dependency_manifest(source_root: str) -> dict:
    """Build a deterministic dependency manifest for all custom nodes under
    *source_root*.

    Scans dependency-relevant files only GÃ‡Ã¶ not entire source trees.
    """
    import sys as _sys
    nodes_manifest: dict[str, dict] = {}
    overall_input: dict[str, dict] = {}
    for node_name in _iter_syncable_custom_node_dirs(source_root):
        node_path = os.path.join(source_root, node_name)
        dep_files = _collect_dependency_file_paths(node_path)
        has_reqs = "requirements.txt" in dep_files
        req_hash = ""
        if has_reqs:
            req_hash = dep_files["requirements.txt"]
        nodes_manifest[node_name] = {
            "has_requirements": has_reqs,
            "dependency_files": dep_files,
            "requirements_hash": req_hash,
        }
        # Only include nodes with non-empty dependency_files in overall hash
        # so adding/removing a no-dependency node does not force a rebuild.
        if dep_files:
            overall_input[node_name] = dep_files

    syncable_node_names = _iter_syncable_custom_node_dirs(source_root)
    dependency_node_names = sorted([
        name for name, data in nodes_manifest.items() if data.get("dependency_files")
    ])
    stable = json.dumps(overall_input, sort_keys=True, ensure_ascii=False, separators=(",", ":"))
    overall_hash = hashlib.sha256(stable.encode("utf-8")).hexdigest()
    return {
        "schema_version": 2,
        "created_by": "comfyapp.py",
        "python_version": f"{_sys.version_info.major}.{_sys.version_info.minor}.{_sys.version_info.micro}",
        "comfyapp_version": COMFYAPP_VERSION,
        "source_root": source_root,
        "syncable_node_names": syncable_node_names,
        "nodes": nodes_manifest,
        "dependency_nodes": dependency_node_names,
        "overall_dependency_hash": overall_hash,
    }


def load_baked_custom_node_dependency_manifest() -> dict:
    """Read the baked dependency manifest from inside the image.

    Returns an empty dict if the manifest does not exist (image was not
    built with the manifest GÃ‡Ã¶ compatibility fallback).
    """
    if not os.path.isfile(BAKED_CUSTOM_NODE_DEPS_MANIFEST_PATH):
        return {}
    try:
        with open(BAKED_CUSTOM_NODE_DEPS_MANIFEST_PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict) and data.get("schema_version") in (1, 2):
            return data
        return {}
    except (json.JSONDecodeError, OSError):
        return {}


def get_runtime_custom_node_source_root_for_dependency_validation() -> str:
    """Return the custom-node source root that actually controls runtime nodes.

    The volume (``CUSTOM_NODES_PATH``) is authoritative for dynamic custom
    nodes.  When the volume is empty or contains only non-syncable entries
    (``.staging``, ``__pycache__``, etc.), the image-baked nodes at
    ``/root/comfy/ComfyUI/custom_nodes`` are used as fallback.

    Uses ``_iter_syncable_custom_node_dirs`` to filter out non-node entries
    so that stray artifacts do not cause false dependency mismatches.
    """
    _raw_entries = len(_safe_listdir(CUSTOM_NODES_PATH)) if os.path.isdir(CUSTOM_NODES_PATH) else 0
    _syncable = _iter_syncable_custom_node_dirs(CUSTOM_NODES_PATH) if os.path.isdir(CUSTOM_NODES_PATH) else []
    if os.path.isdir(CUSTOM_NODES_PATH) and _syncable:
        _used_root = CUSTOM_NODES_PATH
        _source = "volume"
    else:
        _used_root = "/root/comfy/ComfyUI/custom_nodes"
        _source = "image_baked"
    print(
        f"[comfyapp] dependency_validation source_root={_used_root} "
        f"source={_source} "
        f"volume_syncable_nodes={len(_syncable)} "
        f"raw_volume_entries={_raw_entries}"
    )
    return _used_root


def build_current_custom_node_dependency_manifest() -> dict:
    """Build a current dependency manifest from the runtime source root.

    Uses the same scanning rules as ``build_custom_node_dependency_manifest``.
    The source root is determined by
    ``get_runtime_custom_node_source_root_for_dependency_validation()``:
    volume if it has content, otherwise the image-baked custom nodes path.
    """
    return build_custom_node_dependency_manifest(
        get_runtime_custom_node_source_root_for_dependency_validation()
    )


def validate_custom_node_dependencies_prepared() -> dict:
    """Compare the baked image manifest against the current custom-node volume.

    Returns a dict with keys:
    - prepared: bool
    - reason: str
    - baked_hash: str | None
    - current_hash: str | None
    - changed_nodes: list[str]
    """
    baked = load_baked_custom_node_dependency_manifest()
    if not baked:
        return {
            "prepared": False,
            "reason": "baked_manifest_missing",
            "baked_hash": None,
            "current_hash": None,
            "changed_nodes": [],
        }
    try:
        current = build_current_custom_node_dependency_manifest_cached()
    except Exception as exc:
        return {
            "prepared": False,
            "reason": f"current_manifest_invalid:{exc}",
            "baked_hash": baked.get("overall_dependency_hash"),
            "current_hash": None,
            "changed_nodes": [],
        }
    baked_hash = baked.get("overall_dependency_hash", "")
    current_hash = current.get("overall_dependency_hash", "")

    baked_node_names = set(baked.get("syncable_node_names", baked.get("nodes", {}).keys()) or [])
    current_node_names = set(current.get("syncable_node_names", current.get("nodes", {}).keys()) or [])

    # Node set mismatch detection: if baked manifest has no nodes but current does
    if current_node_names and not baked_node_names:
        return {
            "prepared": False,
            "reason": "baked_manifest_has_no_custom_nodes",
            "baked_hash": baked_hash,
            "current_hash": current_hash,
            "changed_nodes": sorted(current_node_names),
        }

    if baked_node_names != current_node_names:
        _ignored_env = os.environ.get("COMFYMODAL_CUSTOM_NODE_SET_MISMATCH_IGNORE", "").strip()
        _ignored = {x.strip() for x in _ignored_env.split(",")} if _ignored_env else set()
        missing_in_baked = sorted(current_node_names - baked_node_names - _ignored)
        extra_in_baked = sorted(baked_node_names - current_node_names - _ignored)
        effective_mismatch = bool(missing_in_baked or extra_in_baked)
        if _ignored:
            print(
                f"[comfyapp] node_set_mismatch_ignored={sorted(_ignored & (current_node_names ^ baked_node_names))} "
                f"(configured via COMFYMODAL_CUSTOM_NODE_SET_MISMATCH_IGNORE)"
            )
        if not effective_mismatch:
            if baked_hash == current_hash:
                return {
                    "prepared": True,
                    "reason": "hash_match_after_ignored_mismatches",
                    "baked_hash": baked_hash,
                    "current_hash": current_hash,
                    "changed_nodes": [],
                }
        return {
            "prepared": False,
            "reason": "custom_node_set_mismatch",
            "baked_hash": baked_hash,
            "current_hash": current_hash,
            "changed_nodes": missing_in_baked,
        }

    if baked_hash == current_hash:
        return {
            "prepared": True,
            "reason": "hash_match",
            "baked_hash": baked_hash,
            "current_hash": current_hash,
            "changed_nodes": [],
        }
    # Find changed nodes
    baked_nodes = baked.get("nodes", {})
    current_nodes = current.get("nodes", {})
    changed = []
    all_names = set(baked_nodes) | set(current_nodes)
    for name in sorted(all_names):
        bn = baked_nodes.get(name, {})
        cn = current_nodes.get(name, {})
        if bn.get("requirements_hash") != cn.get("requirements_hash"):
            changed.append(name)
        elif bn.get("dependency_files") != cn.get("dependency_files"):
            changed.append(name)
    return {
        "prepared": False,
        "reason": "dependency_hash_mismatch",
        "baked_hash": baked_hash,
        "current_hash": current_hash,
        "changed_nodes": changed,
    }


def build_dependency_validation_cache_key(
    baked_hash: str | None,
    current_dep_fingerprint_hash: str,
    source_root_indicator: str,
    repair_mode: str,
    python_version: str = "",
    comfyapp_version: str = "",
    copy_mode: str = "combined",
) -> str:
    """Build a deterministic cache key for dependency validation.

    Includes enough to make stale-cache passes impossible:
    - baked dependency manifest hash
    - current dependency fingerprint hash
    - source root indicator (volume / image_baked)
    - Python major/minor/micro version
    - COMFYAPP_VERSION
    - COMFYMODAL_REQUIREMENTS_REPAIR_MODE
    - custom-node copy mode
    - cache/schema version

    Does NOT include timestamps or source files that don't affect deps.
    """
    hasher = hashlib.sha256()
    hasher.update(f"schema_version={DEPENDENCY_VALIDATION_CACHE_SCHEMA_VERSION}\n".encode())
    hasher.update(f"baked_hash={baked_hash or ''}\n".encode())
    hasher.update(f"dep_fingerprint={current_dep_fingerprint_hash}\n".encode())
    hasher.update(f"source_root={source_root_indicator}\n".encode())
    hasher.update(f"python={python_version or sys.version}\n".encode())
    hasher.update(f"comfyapp={comfyapp_version or COMFYAPP_VERSION}\n".encode())
    hasher.update(f"repair_mode={repair_mode}\n".encode())
    hasher.update(f"copy_mode={copy_mode}\n".encode())
    return hasher.hexdigest()


def _get_custom_node_source_root_indicator() -> str:
    """Return indicator string: 'volume' if volume has syncable nodes, else 'image_baked'."""
    _syncable = _iter_syncable_custom_node_dirs(CUSTOM_NODES_PATH) if os.path.isdir(CUSTOM_NODES_PATH) else []
    if os.path.isdir(CUSTOM_NODES_PATH) and _syncable:
        return "volume"
    return "image_baked"


def _read_deployment_dependency_validation_sentinel(cache_key: str) -> dict | None:
    """Read a deployment sentinel for *cache_key*.

    Returns the sentinel dict if valid (schema version matches, key matches),
    or None if the sentinel is missing, corrupt, or has a mismatched key.
    """
    sentinel_path = os.path.join(
        DEPLOYMENT_DEPENDENCY_VALIDATION_CACHE_DIR, f"{cache_key}.json"
    )
    if not os.path.isfile(sentinel_path):
        return None
    try:
        with open(sentinel_path, "r", encoding="utf-8") as f:
            sentinel = json.load(f)
        if not isinstance(sentinel, dict):
            return None
        if sentinel.get("schema_version") != DEPENDENCY_VALIDATION_CACHE_SCHEMA_VERSION:
            print(f"[comfyapp] dep_validation_sentinel: schema_version mismatch, ignoring")
            return None
        if sentinel.get("cache_key") != cache_key:
            print(f"[comfyapp] dep_validation_sentinel: key mismatch, ignoring")
            return None
        return sentinel
    except (json.JSONDecodeError, OSError) as exc:
        print(f"[comfyapp] dep_validation_sentinel: corrupt ({exc}), ignoring")
        return None


def _write_deployment_dependency_validation_sentinel(
    cache_key: str,
    baked_hash: str | None,
    dep_fingerprint_hash: str,
    repair_mode: str,
    source_root_indicator: str,
    validation_result: dict,
) -> None:
    """Atomically write a deployment sentinel after successful validation.

    Only writes when validation succeeded (prepared=True).
    Uses temp-file + os.replace for atomicity.
    """
    if not validation_result.get("prepared"):
        return
    os.makedirs(DEPLOYMENT_DEPENDENCY_VALIDATION_CACHE_DIR, exist_ok=True)
    sentinel = {
        "schema_version": DEPENDENCY_VALIDATION_CACHE_SCHEMA_VERSION,
        "cache_key": cache_key,
        "created_at": time.time(),
        "baked_hash": baked_hash,
        "dep_fingerprint_hash": dep_fingerprint_hash,
        "repair_mode": repair_mode,
        "source_root": source_root_indicator,
        "validated_node_count": len(validation_result.get("changed_nodes", [])),
        "result": "validated",
        "comfyapp_version": COMFYAPP_VERSION,
    }
    sentinel_path = os.path.join(
        DEPLOYMENT_DEPENDENCY_VALIDATION_CACHE_DIR, f"{cache_key}.json"
    )
    tmp_path = f"{sentinel_path}.tmp.{os.getpid()}"
    try:
        with open(tmp_path, "w", encoding="utf-8") as f:
            json.dump(sentinel, f, indent=2, sort_keys=True)
        os.replace(tmp_path, sentinel_path)
        _commit_volume_async(label="dep_validation_sentinel")
        print(
            f"[comfyapp] dep_validation_sentinel: written key={cache_key[:16]}... "
            f"source={source_root_indicator} nodes={sentinel['validated_node_count']}"
        )
    except Exception as exc:
        print(f"[comfyapp] dep_validation_sentinel: write failed ({exc})")
        # Remove temp file on failure
        try:
            if os.path.isfile(tmp_path):
                os.remove(tmp_path)
        except OSError:
            pass


def _cheap_volume_state_hash() -> str:
    """Compute a hash of custom-node volume state using only stat calls (no content reads).

    Mirrors ``custom_node_volume_state`` GÃ‡Ã¶ returns MD5 hex of
    ``(name, st_mtime_ns, req_mtime_ns)`` tuples for each syncable node.
    Very fast (~1ms for 22 nodes) compared to content fingerprint (~900ms).
    """
    if not os.path.isdir(CUSTOM_NODES_PATH):
        return ""
    state = custom_node_volume_state(CUSTOM_NODES_PATH)
    if not state:
        return ""
    return hashlib.md5(str(state).encode()).hexdigest()


def _run_dependency_validation_with_cache(
    baked: dict | None = None,
    repair_mode: str | None = None,
) -> dict:
    """Run dependency validation with caching (pre-key memory + full key memory + sentinel).

    Returns a dict with all standard validation fields PLUS cache/timing metadata:

    Cache flow:
    0. Ultra-fast pre-key memory check using cheap volume state (avoids fingerprint scan)
    1. Build cheap dependency fingerprint
    2. Compute deterministic cache key
    3. Check per-container full-key memory cache
    4. Check deployment sentinel on volume
    5. Only if both miss, run full validation
    6. On success, write caches + deployment sentinel

    Returns a dict with keys:
    - All keys from validate_custom_node_dependencies_prepared()
    - dependency_validation_start_unix_s
    - dependency_validation_end_unix_s
    - dependency_validation_ms  (same as total_ms, kept for backward compat)
    - dependency_validation_total_ms
    - dependency_pre_key_check_ms
    - dependency_baked_manifest_load_ms
    - dependency_source_root_resolve_ms
    - dependency_fingerprint_ms
    - dependency_cache_key_ms
    - dependency_memory_lookup_ms
    - dependency_sentinel_lookup_ms
    - dependency_full_validation_ms
    - dependency_sentinel_write_ms
    - and all existing dependency_validation_* fields
    """
    global _dependency_validation_memory_cache, _dependency_validation_memory_cache_key, _dep_validation_pre_key

    _t_total = time.time()
    _t_phase = _t_total

    def _elapsed_ms(since: float) -> float:
        return round((time.time() - since) * 1000, 2)

    def _mark_phase() -> float:
        nonlocal _t_phase
        now = time.time()
        d = round((now - _t_phase) * 1000, 2)
        _t_phase = now
        return d

    result: dict = {
        "dependency_validation_start_unix_s": _t_total,
        "dependency_validation_cache_layer": "none",
        "dependency_validation_cache_key": "",
        "dependency_validation_cache_hit": False,
        "dependency_validation_baked_hash": None,
        "dependency_validation_current_hash": None,
        "dependency_validation_changed_nodes": [],
        "dependency_validation_repair_mode": repair_mode or "",
        "dependency_total_ms": 0.0,
        "dependency_pre_key_check_ms": 0.0,
        "dependency_baked_manifest_load_ms": 0.0,
        "dependency_source_root_resolve_ms": 0.0,
        "dependency_fingerprint_ms": 0.0,
        "dependency_cache_key_ms": 0.0,
        "dependency_memory_lookup_ms": 0.0,
        "dependency_sentinel_lookup_ms": 0.0,
        "dependency_full_validation_ms": 0.0,
        "dependency_sentinel_write_ms": 0.0,
    }

    # GÃ¶Ã‡GÃ¶Ã‡ Step 1: Load baked manifest first (needed for pre-key check) GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡
    if baked is None:
        baked = load_baked_custom_node_dependency_manifest()
    _baked_load_ms = _mark_phase()
    result["dependency_baked_manifest_load_ms"] = _baked_load_ms

    # GÃ¶Ã‡GÃ¶Ã‡ Step 0: Pre-key memory fast path GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡
    # Uses cheap volume state (stat calls only, no content reads) to avoid
    # the expensive dependency fingerprint scan (~900ms) on subsequent requests
    # in the same warm container.
    _pre_key_vol_hash = _cheap_volume_state_hash()
    _pre_key_resolve_ms = _mark_phase()
    result["dependency_source_root_resolve_ms"] = _pre_key_resolve_ms

    if not baked:
        result["dependency_validation_end_unix_s"] = time.time()
        total = _elapsed_ms(_t_total)
        result["dependency_validation_ms"] = total
        result["dependency_total_ms"] = total
        result["dependency_validation_result"] = "baked_manifest_missing"
        result["dependency_validation_reason"] = "baked_manifest_missing"
        val = {
            "prepared": False,
            "reason": "baked_manifest_missing",
            "baked_hash": None,
            "current_hash": None,
            "changed_nodes": [],
        }
        result.update(val)
        return result

    baked_hash = baked.get("overall_dependency_hash", "")
    if repair_mode is None:
        repair_mode = REQUIREMENTS_REPAIR_MODE.strip().lower()
    if repair_mode not in ("off", "fail_fast", "dev"):
        repair_mode = "fail_fast"
    source_root_indicator = _get_custom_node_source_root_indicator()

    if _dep_validation_pre_key is not None:
        _pk = _dep_validation_pre_key
        _pk_mode = _pk.get("repair_mode")
        _pk_sri = _pk.get("source_root_indicator")
        _pk_vsh = _pk.get("volume_state_hash")
        _pk_bh = _pk.get("baked_hash")
        _pk_match = (
            _pk_bh == baked_hash
            and _pk_mode == repair_mode
            and _pk_sri == source_root_indicator
            and _pk_vsh == _pre_key_vol_hash
        )
        _pk_result = _pk.get("result")
        if _pk_match and isinstance(_pk_result, dict) and _pk_result.get("prepared"):
            _pre_key_ms = _mark_phase()
            result["dependency_pre_key_check_ms"] = _pre_key_ms
            result["dependency_total_ms"] = _elapsed_ms(_t_total)
            result["dependency_validation_ms"] = result["dependency_total_ms"]
            result["dependency_validation_end_unix_s"] = time.time()
            result["dependency_validation_result"] = "memory_cache_hit"
            result["dependency_validation_cache_layer"] = "memory_pre_key"
            result["dependency_validation_cache_hit"] = True
            result["dependency_validation_reason"] = "pre_key_memory_hit"
            for _k, _v in _pk_result.items():
                if _k not in result:
                    result[_k] = _v
            print(
                f"[comfyapp] dep_validation_cache: pre-key memory hit "
                f"total_ms={result['dependency_total_ms']} "
                f"pre_key_check_ms={_pre_key_ms}"
            )
            return result

    # GÃ¶Ã‡GÃ¶Ã‡ Step 2: Build cheap dependency fingerprint GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡
    source_root = get_runtime_custom_node_source_root_for_dependency_validation()
    dep_fp = custom_node_dependency_fingerprint(source_root)
    dep_fingerprint_hash = dep_fp.get("overall_dependency_hash", "")
    _fingerprint_ms = _mark_phase()
    result["dependency_fingerprint_ms"] = _fingerprint_ms

    # GÃ¶Ã‡GÃ¶Ã‡ Step 3: Compute cache key GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡
    cache_key = build_dependency_validation_cache_key(
        baked_hash=baked_hash,
        current_dep_fingerprint_hash=dep_fingerprint_hash,
        source_root_indicator=source_root_indicator,
        repair_mode=repair_mode,
    )
    result["dependency_validation_cache_key"] = cache_key
    result["dependency_validation_baked_hash"] = baked_hash
    result["dependency_validation_repair_mode"] = repair_mode
    _cache_key_ms = _mark_phase()
    result["dependency_cache_key_ms"] = _cache_key_ms

    # GÃ¶Ã‡GÃ¶Ã‡ Step 4: Check per-container full-key memory cache GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡
    if _dependency_validation_memory_cache_key == cache_key and _dependency_validation_memory_cache:
        cached = _dependency_validation_memory_cache
        if cached.get("prepared"):
            _mem_ms = _mark_phase()
            result["dependency_memory_lookup_ms"] = _mem_ms
            result["dependency_validation_end_unix_s"] = time.time()
            result["dependency_total_ms"] = _elapsed_ms(_t_total)
            result["dependency_validation_ms"] = result["dependency_total_ms"]
            result["dependency_validation_result"] = "memory_cache_hit"
            result["dependency_validation_cache_layer"] = "memory"
            result["dependency_validation_cache_hit"] = True
            result["dependency_validation_reason"] = "memory_cache_hit"
            result.update(cached)
            print(
                f"[comfyapp] dep_validation_cache: full-key memory hit "
                f"total_ms={result['dependency_total_ms']} "
                f"fingerprint_ms={_fingerprint_ms} "
                f"mem_lookup_ms={_mem_ms}"
            )
            return result
        # Don't cache failures; fall through

    _mem_lookup_ms = _mark_phase()
    result["dependency_memory_lookup_ms"] = _mem_lookup_ms

    # GÃ¶Ã‡GÃ¶Ã‡ Step 5: Check deployment sentinel on volume GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡
    sentinel = _read_deployment_dependency_validation_sentinel(cache_key)
    if sentinel is not None:
        val = {
            "prepared": True,
            "reason": "deployment_sentinel_match",
            "baked_hash": baked_hash,
            "current_hash": dep_fingerprint_hash,
            "changed_nodes": [],
        }
        result.update(val)
        _sentinel_ms = _mark_phase()
        result["dependency_sentinel_lookup_ms"] = _sentinel_ms
        result["dependency_validation_end_unix_s"] = time.time()
        result["dependency_total_ms"] = _elapsed_ms(_t_total)
        result["dependency_validation_ms"] = result["dependency_total_ms"]
        result["dependency_validation_result"] = "deployment_cache_hit"
        result["dependency_validation_cache_layer"] = "deployment_sentinel"
        result["dependency_validation_cache_hit"] = True
        result["dependency_validation_reason"] = "deployment_sentinel_match"
        _dependency_validation_memory_cache = dict(val)
        _dependency_validation_memory_cache_key = cache_key
        _pkey = {
            "baked_hash": baked_hash,
            "repair_mode": repair_mode,
            "source_root_indicator": source_root_indicator,
            "volume_state_hash": _pre_key_vol_hash,
            "result": dict(val),
        }
        _dep_validation_pre_key = _pkey
        print(f"[comfyapp] dep_validation_cache: deployment sentinel hit key={cache_key[:16]}...")
        return result

    _sentinel_lookup_ms = _mark_phase()
    result["dependency_sentinel_lookup_ms"] = _sentinel_lookup_ms

    # GÃ¶Ã‡GÃ¶Ã‡ Step 6: Fast-path hash compare GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡
    if baked_hash and dep_fingerprint_hash and baked_hash == dep_fingerprint_hash:
        val = {
            "prepared": True,
            "reason": "hash_match_fast_path",
            "baked_hash": baked_hash,
            "current_hash": dep_fingerprint_hash,
            "changed_nodes": [],
        }
        result.update(val)
        _write_deployment_dependency_validation_sentinel(
            cache_key, baked_hash, dep_fingerprint_hash,
            repair_mode, source_root_indicator, val,
        )
        _sentinel_write_ms = _mark_phase()
        result["dependency_sentinel_write_ms"] = _sentinel_write_ms
        result["dependency_validation_end_unix_s"] = time.time()
        result["dependency_total_ms"] = _elapsed_ms(_t_total)
        result["dependency_validation_ms"] = result["dependency_total_ms"]
        result["dependency_validation_result"] = "hash_match_fast_path"
        result["dependency_validation_cache_layer"] = "baked_hash_fast_path"
        result["dependency_validation_cache_hit"] = True
        result["dependency_validation_reason"] = "hash_match_fast_path"
        _dependency_validation_memory_cache = dict(val)
        _dependency_validation_memory_cache_key = cache_key
        _pkey = {
            "baked_hash": baked_hash,
            "repair_mode": repair_mode,
            "source_root_indicator": source_root_indicator,
            "volume_state_hash": _pre_key_vol_hash,
            "result": dict(val),
        }
        _dep_validation_pre_key = _pkey
        print(
            f"[comfyapp] dep_validation_cache: hash fast-path "
            f"total_ms={result['dependency_total_ms']} "
            f"fingerprint_ms={_fingerprint_ms} "
            f"sentinel_write_ms={_sentinel_write_ms}"
        )
        return result

    # GÃ¶Ã‡GÃ¶Ã‡ Step 7: Full validation (missed all caches) GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡
    val = validate_custom_node_dependencies_prepared()
    result.update(val)
    result["dependency_validation_current_hash"] = val.get("current_hash", dep_fingerprint_hash)
    result["dependency_validation_changed_nodes"] = val.get("changed_nodes", [])
    _full_val_ms = _mark_phase()
    result["dependency_full_validation_ms"] = _full_val_ms

    if val.get("prepared"):
        result["dependency_validation_result"] = "validated"
        result["dependency_validation_cache_layer"] = "none"
        result["dependency_validation_cache_hit"] = False
        result["dependency_validation_reason"] = val.get("reason", "validated")
        _dependency_validation_memory_cache = dict(val)
        _dependency_validation_memory_cache_key = cache_key
        _write_deployment_dependency_validation_sentinel(
            cache_key, baked_hash, dep_fingerprint_hash,
            repair_mode, source_root_indicator, val,
        )
        _sentinel_write2_ms = _mark_phase()
        result["dependency_sentinel_write_ms"] = result.get("dependency_sentinel_write_ms", 0.0) + _sentinel_write2_ms
        _pkey = {
            "baked_hash": baked_hash,
            "repair_mode": repair_mode,
            "source_root_indicator": source_root_indicator,
            "volume_state_hash": _pre_key_vol_hash,
            "result": dict(val),
        }
        _dep_validation_pre_key = _pkey
    else:
        result["dependency_validation_result"] = "failed"
        result["dependency_validation_cache_layer"] = "none"
        result["dependency_validation_cache_hit"] = False
        result["dependency_validation_reason"] = val.get("reason", "validation_failed")
        _dependency_validation_memory_cache_key = ""
        _dependency_validation_memory_cache = {}
        _dep_validation_pre_key = None

    result["dependency_validation_end_unix_s"] = time.time()
    result["dependency_total_ms"] = _elapsed_ms(_t_total)
    result["dependency_validation_ms"] = result["dependency_total_ms"]
    print(
        f"[comfyapp] dep_validation_cache: miss result={result['dependency_validation_result']} "
        f"total_ms={result['dependency_total_ms']} "
        f"fingerprint_ms={_fingerprint_ms} "
        f"full_val_ms={_full_val_ms} "
        f"key={cache_key[:16]}..."
    )
    return result


# GÃ¶Ã‡GÃ¶Ã‡ PART 11: Known-good workflow profiles GÃ¶Ã‡GÃ¶Ã‡
def load_known_good_workflow_profiles() -> dict:
    """Load known-good workflow profiles from the volume."""
    try:
        if os.path.isfile(KNOWN_GOOD_WORKFLOW_PROFILES_PATH):
            with open(KNOWN_GOOD_WORKFLOW_PROFILES_PATH, "r") as f:
                data = json.load(f)
            if isinstance(data, dict):
                return data
    except (json.JSONDecodeError, OSError):
        pass
    return {}


import threading as _threading
_volume_commit_lock = _threading.Lock()
_volume_commit_inflight_labels: set[str] = set()
_volume_commit_dirty_labels: set[str] = set()

# GÃ¶Ã‡GÃ¶Ã‡ Active model-read registry (module-global) GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡
# Tracks every in-flight model-file read so any consumer (cached_load,
# restore preload worker, actual_load worker, etc.) can avoid starting
# a duplicate volume read for the same canonical model path.
# Module-global because patched load functions and background threads
# may run before any per-instance fields are initialised.
#
# Each entry is a dict with keys:
#   canonical_key, owner, path, start_time, status,
#   future (concurrent.futures.Future | None),
#   event (threading.Event | None),
#   result_available (bool), error (str), completed_at (float)
_ACTIVE_MODEL_READS: dict[str, dict] = {}
_ACTIVE_MODEL_READS_LOCK = _threading.RLock()
_FUSE_LARGE_READS_COND = _threading.Condition(_ACTIVE_MODEL_READS_LOCK)
_FUSE_LARGE_READS_IN_PROGRESS = 0
_FUSE_LARGE_READS_ACTIVE: dict[str, dict] = {}


def _classify_fuse_read(path: str = "", *, loader_type: str = "", caller_hint: str = "") -> dict:
    """Classify a model path as a large or small Modal Volume/FUSE read."""
    hint = (caller_hint or "").strip().lower()
    if hint in ("large", "small"):
        is_large = hint == "large"
        return {
            "active_read_size_bytes": -1,
            "active_read_size_mb": -1.0,
            "active_read_is_large": 1 if is_large else 0,
            "active_read_classification_source": "caller_hint",
        }

    size_bytes = -1
    if path:
        try:
            size_bytes = os.path.getsize(path)
        except OSError:
            size_bytes = -1
    if size_bytes >= 0:
        size_mb = round(size_bytes / (1024 * 1024), 1)
        return {
            "active_read_size_bytes": size_bytes,
            "active_read_size_mb": size_mb,
            "active_read_is_large": 1 if size_mb >= FUSE_LARGE_READ_MIN_MB else 0,
            "active_read_classification_source": "file_size",
        }

    lower_path = (path or "").lower()
    lower_loader = (loader_type or "").lower()
    looks_like_model = lower_path.endswith((".safetensors", ".ckpt", ".pt", ".pth", ".bin")) or any(
        token in lower_loader for token in ("unet", "clip", "checkpoint", "vae")
    )
    return {
        "active_read_size_bytes": -1,
        "active_read_size_mb": -1.0,
        "active_read_is_large": 1 if looks_like_model else 0,
        "active_read_classification_source": "unknown_fallback",
    }


def _active_read_priority(owner: str = "", loader_type: str = "", path: str = "", phase: str = "") -> int:
    """Higher number means higher priority. Inferred from role, not filename."""
    blob = " ".join(str(v).lower() for v in (owner, loader_type, path, phase) if v)
    if any(token in blob for token in ("unet", "checkpoint", "diffusion")):
        return 100
    if any(token in blob for token in ("clip", "text_encoder", "text_encoders")):
        return 80
    if "vae" in blob:
        return 40
    return 10


def _running_large_reads_locked() -> list[dict]:
    return [
        dict(v)
        for v in _ACTIVE_MODEL_READS.values()
        if v.get("status") == "running" and int(v.get("active_read_is_large", 0)) == 1
    ]


def _release_fuse_large_read_slot_locked(canonical_key: str, entry: dict) -> None:
    global _FUSE_LARGE_READS_IN_PROGRESS
    if not entry.get("active_read_large_slot_acquired"):
        return
    _FUSE_LARGE_READS_IN_PROGRESS = max(0, _FUSE_LARGE_READS_IN_PROGRESS - 1)
    _FUSE_LARGE_READS_ACTIVE.pop(canonical_key, None)
    entry["active_read_large_slots_used_at_end"] = _FUSE_LARGE_READS_IN_PROGRESS
    entry["active_read_concurrent_large_reads_at_end"] = len(_running_large_reads_locked())
    _FUSE_LARGE_READS_COND.notify_all()


def _register_active_model_read(canonical_key: str, owner: str, path: str = "",
                                 future=None, event=None, loader_type: str = "",
                                 phase: str = "", caller_hint: str = "",
                                 priority: int | None = None) -> str:
    """Register a model-file read before starting the actual loader call.

    If a running entry already exists for *canonical_key*, returns
    ``"duplicate"`` and does NOT overwrite.  Otherwise creates the
    entry and returns ``"registered"``.

    The caller **must** later call ``_complete_active_model_read()``
    or ``_fail_active_model_read()``.
    """
    global _FUSE_LARGE_READS_IN_PROGRESS
    classification = _classify_fuse_read(path, loader_type=loader_type, caller_hint=caller_hint)
    active_read_priority = priority if priority is not None else _active_read_priority(owner, loader_type, path, phase)
    is_large = int(classification.get("active_read_is_large", 0)) == 1
    with _ACTIVE_MODEL_READS_LOCK:
        existing = _ACTIVE_MODEL_READS.get(canonical_key)
        if existing and existing["status"] in ("queued", "running"):
            print(f"[active_read] duplicate_read_prevented key={canonical_key[:80]} "
                  f"owner_existing={existing['owner']} owner_new={owner} "
                  f"active_read_attached_existing_future=1 active_read_duplicate_prevented=1")
            return "duplicate"
        entry = {
            "canonical_key": canonical_key,
            "owner": owner,
            "path": path,
            "start_time": time.time(),
            "status": "queued" if (FUSE_READ_GOVERNOR_ENABLED and is_large) else "running",
            "future": future,
            "event": event or _threading.Event(),
            "result_available": False,
            "error": "",
            "completed_at": 0.0,
            "loader_type": loader_type,
            "phase": phase,
            "active_read_governor_enabled": 1 if FUSE_READ_GOVERNOR_ENABLED else 0,
            "active_read_priority": active_read_priority,
            "active_read_queue_enter_ms": 0.0,
            "active_read_queue_exit_ms": 0.0,
            "active_read_queue_wait_ms": 0.0,
            "active_read_large_slots_used_at_enter": 0,
            "active_read_large_slots_used_at_start": 0,
            "active_read_large_slots_used_at_end": 0,
            "active_read_concurrent_large_reads_at_start": 0,
            "active_read_concurrent_large_reads_at_end": 0,
            "active_read_attached_existing_future": 0,
            "active_read_duplicate_prevented": 0,
            "active_read_large_slot_acquired": False,
            **classification,
        }
        _ACTIVE_MODEL_READS[canonical_key] = entry
    if is_large and FUSE_READ_GOVERNOR_ENABLED:
        queue_enter = time.time()
        with _FUSE_LARGE_READS_COND:
            entry = _ACTIVE_MODEL_READS.get(canonical_key)
            if entry is None:
                return "missing"
            entry["active_read_queue_enter_ms"] = round((queue_enter - entry["start_time"]) * 1000, 1)
            entry["active_read_large_slots_used_at_enter"] = _FUSE_LARGE_READS_IN_PROGRESS
            while _FUSE_LARGE_READS_IN_PROGRESS >= FUSE_LARGE_READ_CONCURRENCY:
                _FUSE_LARGE_READS_COND.wait(timeout=0.05)
            _FUSE_LARGE_READS_IN_PROGRESS += 1
            _FUSE_LARGE_READS_ACTIVE[canonical_key] = {
                "owner": owner,
                "key": canonical_key,
                "priority": active_read_priority,
                "phase": phase,
            }
            queue_exit = time.time()
            entry["status"] = "running"
            entry["active_read_queue_exit_ms"] = round((queue_exit - entry["start_time"]) * 1000, 1)
            entry["active_read_queue_wait_ms"] = round((queue_exit - queue_enter) * 1000, 1)
            entry["active_read_large_slots_used_at_start"] = _FUSE_LARGE_READS_IN_PROGRESS
            entry["active_read_concurrent_large_reads_at_start"] = len(_running_large_reads_locked())
            entry["active_read_large_slot_acquired"] = True
            if _FUSE_LARGE_READS_IN_PROGRESS > FUSE_LARGE_READ_CONCURRENCY:
                others = [v for k, v in _FUSE_LARGE_READS_ACTIVE.items() if k != canonical_key]
                other = others[0] if others else {}
                print(
                    f"[active_read] active_read_governor_violation=1 "
                    f"owner_a={other.get('owner','?')} owner_b={owner} "
                    f"key_a={str(other.get('key',''))[:80]} key_b={canonical_key[:80]} "
                    f"priority_a={other.get('priority','?')} priority_b={active_read_priority} "
                    f"phase_a={other.get('phase','?')} phase_b={phase}"
                )
    elif is_large:
        with _ACTIVE_MODEL_READS_LOCK:
            entry = _ACTIVE_MODEL_READS.get(canonical_key)
            running_large = _running_large_reads_locked()
            if entry is not None:
                entry["active_read_concurrent_large_reads_at_start"] = len(running_large)
            if len(running_large) > 1:
                print(f"[active_read] active_read_large_overlap_observed=1 concurrent_large_reads={len(running_large)}")
    else:
        with _ACTIVE_MODEL_READS_LOCK:
            entry = _ACTIVE_MODEL_READS.get(canonical_key)
            if entry is not None:
                entry["active_read_concurrent_large_reads_at_start"] = len(_running_large_reads_locked())
    with _ACTIVE_MODEL_READS_LOCK:
        entry = _ACTIVE_MODEL_READS.get(canonical_key, {})
        _log_fields = dict(entry)
    print(
        f"[active_read] registered owner={owner} key={canonical_key[:80]} "
        f"active_read_governor_enabled={_log_fields.get('active_read_governor_enabled', 0)} "
        f"active_read_priority={_log_fields.get('active_read_priority', 0)} "
        f"active_read_size_bytes={_log_fields.get('active_read_size_bytes', -1)} "
        f"active_read_size_mb={_log_fields.get('active_read_size_mb', -1.0)} "
        f"active_read_is_large={_log_fields.get('active_read_is_large', 0)} "
        f"active_read_classification_source={_log_fields.get('active_read_classification_source', '?')} "
        f"active_read_queue_enter_ms={_log_fields.get('active_read_queue_enter_ms', 0.0)} "
        f"active_read_queue_exit_ms={_log_fields.get('active_read_queue_exit_ms', 0.0)} "
        f"active_read_queue_wait_ms={_log_fields.get('active_read_queue_wait_ms', 0.0)} "
        f"active_read_large_slots_used_at_enter={_log_fields.get('active_read_large_slots_used_at_enter', 0)} "
        f"active_read_large_slots_used_at_start={_log_fields.get('active_read_large_slots_used_at_start', 0)} "
        f"active_read_concurrent_large_reads_at_start={_log_fields.get('active_read_concurrent_large_reads_at_start', 0)} "
        f"active_read_attached_existing_future={_log_fields.get('active_read_attached_existing_future', 0)} "
        f"active_read_duplicate_prevented={_log_fields.get('active_read_duplicate_prevented', 0)}"
    )
    return "registered"


def _attach_active_model_read_future(canonical_key: str, future) -> None:
    """Attach a concurrent.futures.Future or threading.Thread to an
    existing active-read entry.  Also ensures an event exists."""
    with _ACTIVE_MODEL_READS_LOCK:
        entry = _ACTIVE_MODEL_READS.get(canonical_key)
        if entry is None:
            return
        entry["future"] = future
        entry["active_read_attached_existing_future"] = 1
        if entry.get("event") is None:
            entry["event"] = _threading.Event()
    print(f"[active_read] attached_future owner={entry['owner']} key={canonical_key[:80]} active_read_attached_existing_future=1")


def _complete_active_model_read(canonical_key: str) -> None:
    """Mark a read completed and signal any waiters."""
    with _ACTIVE_MODEL_READS_LOCK:
        entry = _ACTIVE_MODEL_READS.get(canonical_key)
        if entry is None:
            return
        _release_fuse_large_read_slot_locked(canonical_key, entry)
        entry["status"] = "completed"
        entry["result_available"] = True
        entry["completed_at"] = time.time()
        ev = entry.get("event")
        _ACTIVE_MODEL_READS.pop(canonical_key, None)
    if ev is not None:
        ev.set()
    print(f"[active_read] completed owner={entry['owner']} key={canonical_key[:80]}")


def _fail_active_model_read(canonical_key: str, error: str = "") -> None:
    """Mark a read failed and signal any waiters."""
    with _ACTIVE_MODEL_READS_LOCK:
        entry = _ACTIVE_MODEL_READS.get(canonical_key)
        if entry is None:
            return
        _release_fuse_large_read_slot_locked(canonical_key, entry)
        entry["status"] = "failed"
        entry["result_available"] = True
        if error:
            entry["error"] = error
        entry["completed_at"] = time.time()
        ev = entry.get("event")
        _ACTIVE_MODEL_READS.pop(canonical_key, None)
    if ev is not None:
        ev.set()
    print(f"[active_read] failed owner={entry['owner']} key={canonical_key[:80]} error={error[:120]}")


def _count_active_model_reads() -> int:
    """Return the current number of active model reads (for diagnostics)."""
    with _ACTIVE_MODEL_READS_LOCK:
        return len(_ACTIVE_MODEL_READS)


def _check_active_model_read(canonical_key: str) -> dict | None:
    """Return a snapshot of the registry entry if still running, else None.

    The snapshot includes ``future`` and ``event`` so the caller can
    wait outside the lock.
    """
    with _ACTIVE_MODEL_READS_LOCK:
        entry = _ACTIVE_MODEL_READS.get(canonical_key)
        if entry and entry["status"] in ("queued", "running"):
            return dict(entry)
    return None


def _wait_for_active_model_read(canonical_key: str, reason: str = "") -> dict:
    """Wait for an active model read to complete.

    Must be called *outside* ``_ACTIVE_MODEL_READS_LOCK``.

    Returns a dict::

        {"waited": bool, "wait_ms": float, "status": str | None,
         "owner": str | None, "error": str}
    """
    # Snapshot under lock
    with _ACTIVE_MODEL_READS_LOCK:
        entry = _ACTIVE_MODEL_READS.get(canonical_key)
        if entry is None:
            return {"waited": False, "wait_ms": 0.0, "status": None,
                    "owner": None, "error": "no_entry"}
        if entry["status"] not in ("queued", "running"):
            return {"waited": False, "wait_ms": 0.0,
                    "status": entry["status"], "owner": entry.get("owner"),
                    "error": entry.get("error", "")}
        fut = entry.get("future")
        ev = entry.get("event")
        owner = entry.get("owner", "?")
    # Wait outside lock
    waited = False
    t0 = time.time()
    if fut is not None:
        if hasattr(fut, "result"):
            try:
                fut.result()
                waited = True
            except Exception:
                pass
        elif hasattr(fut, "join"):
            fut.join()
            waited = True
    elif ev is not None:
        ev.wait(timeout=60)
        waited = ev.is_set()
    wait_ms = round((time.time() - t0) * 1000, 1)
    # After wait, re-check status
    with _ACTIVE_MODEL_READS_LOCK:
        entry2 = _ACTIVE_MODEL_READS.get(canonical_key)
        if entry2 is None:
            return {"waited": waited, "wait_ms": wait_ms,
                    "status": "completed", "owner": owner, "error": ""}
        return {"waited": waited, "wait_ms": wait_ms,
                "status": entry2["status"], "owner": owner,
                "error": entry2.get("error", "")}


def _active_model_read_snapshot() -> dict:
    """Return a copy of the entire registry for diagnostics (no future/event)."""
    with _ACTIVE_MODEL_READS_LOCK:
        out = {}
        for k, v in _ACTIVE_MODEL_READS.items():
            out[k] = {kk: vv for kk, vv in v.items() if kk not in ("future", "event")}
        return out


def _canonical_model_read_key(model_path: str, loader_fn_name: str = "",
                               model_role: str = "", folder: str = "") -> str:
    """Build a canonical key for the active model-read registry.

    Uses normalized realpath + loader function + model role to avoid collisions.
    Does NOT include workflow hash, GPU name, or clip_type unless the loaded
    object genuinely depends on them.
    """
    normalized = os.path.realpath(model_path) if model_path else model_path
    normalized = os.path.normcase(os.path.normpath(normalized))
    parts = [normalized]
    if loader_fn_name:
        parts.append(f"fn={loader_fn_name}")
    if model_role:
        parts.append(f"role={model_role}")
    if folder:
        parts.append(f"folder={folder}")
    return "|".join(parts)


def _is_graph_loader_joinable(canonical_key: str) -> tuple:
    """Check if a speculative load can safely join the graph loader's read.

    Returns (is_joinable: bool, reason: str).
    The key must match exactly GÃ‡Ã¶ same loader function, same role, same path.
    """
    with _ACTIVE_MODEL_READS_LOCK:
        entry = _ACTIVE_MODEL_READS.get(canonical_key)
        if entry is None:
            return False, "no_active_read"
        if entry["status"] not in ("queued", "running"):
            return False, f"read_not_running:{entry['status']}"
        if entry.get("future") is None and entry.get("event") is None:
            return False, "no_waitable"
        return True, "joinable"


# GÃ¶Ã‡GÃ¶Ã‡ Thread-local model-load context GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡GÃ¶Ã‡
# Used by cached_load() to distinguish actual_load workers from graph_loader
# when registering an active model read.  Thread-local because actual_load
# workers run in background threads and must not share state with the main
# request thread.
_MODEL_LOAD_CONTEXT = _threading.local()


@contextlib.contextmanager
def _model_load_context(owner: str = "graph_loader", loader_type: str = "",
                         actual_key=None, canonical_path: str = "",
                         record_id: str = ""):
    """Context manager that sets thread-local model-load attribution.

    Within the ``with`` block, any call to ``cached_load()`` (the patched
    ``load_torch_file``) will use the given *owner* and *loader_type*
    for active-read registration instead of the default ``graph_loader``.
    """
    prev_owner = getattr(_MODEL_LOAD_CONTEXT, "owner", None)
    prev_loader = getattr(_MODEL_LOAD_CONTEXT, "loader_type", None)
    prev_actual_key = getattr(_MODEL_LOAD_CONTEXT, "actual_key", None)
    prev_path = getattr(_MODEL_LOAD_CONTEXT, "canonical_path", None)
    prev_rid = getattr(_MODEL_LOAD_CONTEXT, "record_id", None)

    _MODEL_LOAD_CONTEXT.owner = owner
    _MODEL_LOAD_CONTEXT.loader_type = loader_type
    _MODEL_LOAD_CONTEXT.actual_key = actual_key
    _MODEL_LOAD_CONTEXT.canonical_path = canonical_path
    _MODEL_LOAD_CONTEXT.record_id = record_id
    try:
        yield
    finally:
        if prev_owner is not None:
            _MODEL_LOAD_CONTEXT.owner = prev_owner
        else:
            delattr(_MODEL_LOAD_CONTEXT, "owner")
        if prev_loader is not None:
            _MODEL_LOAD_CONTEXT.loader_type = prev_loader
        else:
            delattr(_MODEL_LOAD_CONTEXT, "loader_type")
        if prev_actual_key is not None:
            _MODEL_LOAD_CONTEXT.actual_key = prev_actual_key
        else:
            delattr(_MODEL_LOAD_CONTEXT, "actual_key")
        if prev_path is not None:
            _MODEL_LOAD_CONTEXT.canonical_path = prev_path
        else:
            delattr(_MODEL_LOAD_CONTEXT, "canonical_path")
        if prev_rid is not None:
            _MODEL_LOAD_CONTEXT.record_id = prev_rid
        else:
            delattr(_MODEL_LOAD_CONTEXT, "record_id")


def _commit_volume_async(label: str = "") -> None:
    """Schedule an asynchronous ``vol.commit()`` in a daemon thread.

    Uses a loopGÃ‡Ã¦based worker per label so no followGÃ‡Ã¦up depth cap can
    drop a dirty write:

    * If no commit is running for *label*, start one.
    * If a commit is already running, mark *label* dirty and return.
    * The running worker loops until no dirty marker remains.
    """
    import threading
    with _volume_commit_lock:
        if label and label in _volume_commit_inflight_labels:
            _volume_commit_dirty_labels.add(label)
            print(
                f"[comfyapp] volume_commit_async_deferred "
                f"label={label} reason=already_in_flight_marked_dirty"
            )
            return
        if label:
            _volume_commit_inflight_labels.add(label)
    if label:
        print(f"[comfyapp] volume_commit_async_started label={label}")
    t = threading.Thread(target=_commit_worker, args=(label,), daemon=True)
    t.start()


def _commit_worker(label: str) -> None:
    """Loop: commit until no dirty marker remains for this label."""
    while True:
        try:
            vol.commit()
            print(f"[comfyapp] volume_commit_async_finished label={label}")
        except Exception as exc:
            print(f"[comfyapp] volume_commit_async_failed label={label} error={exc}")
        with _volume_commit_lock:
            if label and label in _volume_commit_dirty_labels:
                _volume_commit_dirty_labels.discard(label)
                print(f"[comfyapp] volume_commit_async_followup_started label={label}")
                continue
            if label:
                _volume_commit_inflight_labels.discard(label)
            break


def save_known_good_workflow_profiles(profiles: dict) -> None:
    """Persist known-good workflow profiles to the volume."""
    try:
        os.makedirs(os.path.dirname(KNOWN_GOOD_WORKFLOW_PROFILES_PATH), exist_ok=True)
        tmp = f"{KNOWN_GOOD_WORKFLOW_PROFILES_PATH}.tmp"
        with open(tmp, "w") as f:
            json.dump(profiles, f, indent=2, sort_keys=True)
        os.replace(tmp, KNOWN_GOOD_WORKFLOW_PROFILES_PATH)
        _commit_volume_async(label="known_good_profiles")
    except Exception as exc:
        print(f"[comfyapp] failed to save known-good profiles: {exc}")


def _build_known_good_profile_key(profile: dict, workflow: dict | None = None) -> str:
    payload = {
        k: v for k, v in dict(profile or {}).items()
        if k not in {"workflow_hash", "profile_key"}
    }
    if isinstance(workflow, dict):
        payload["required_class_types"] = sorted({
            spec.get("class_type", "")
            for spec in workflow.values()
            if isinstance(spec, dict) and isinstance(spec.get("class_type"), str) and spec.get("class_type")
        })
    compact = json.dumps(payload, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(compact.encode("utf-8")).hexdigest()[:16]


def _is_known_good_workflow_profile(workflow_hash: str, profile: dict) -> bool:
    """Return True if this workflow/profile is known-good (previously succeeded)."""
    profiles = load_known_good_workflow_profiles()
    if workflow_hash in profiles:
        return True
    mode = profile.get("mode", "")
    if mode == "checkpoint":
        ckpt = profile.get("checkpoint", "")
        return any(
            p.get("mode") == "checkpoint" and p.get("checkpoint") == ckpt
            for p in profiles.values()
        )
    elif mode == "split":
        unet = profile.get("unet", "")
        return any(
            p.get("mode") == "split" and p.get("unet") == unet
            for p in profiles.values()
        )
    return False


def _mark_known_good_workflow_profile(workflow_hash: str, profile: dict, workflow: dict | None = None) -> bool:
    """Mark a workflow/profile as known-good after successful execution.

    Returns True if a new or changed entry was persisted and a volume
    commit was scheduled.  Returns False when the entry already exists
    and is identical (no commit scheduled).
    """
    profiles = load_known_good_workflow_profiles()
    profile_key = _build_known_good_profile_key(profile, workflow)
    new_entry = {
        "mode": profile.get("mode", ""),
        "workflow_hash": workflow_hash,
        "profile_key": profile_key,
        **profile,
    }
    existing = profiles.get(workflow_hash)
    if existing is not None and existing == new_entry:
        print(f"[comfyapp] marked known-good workflow hash={workflow_hash} changed=0 (identical)")
        return False
    for existing_hash, existing_entry in profiles.items():
        existing_key = existing_entry.get("profile_key") or _build_known_good_profile_key(existing_entry)
        if existing_key == profile_key and existing_hash != workflow_hash:
            print(
                f"[comfyapp] known_good_profile status=unchanged_profile_key "
                f"workflow_hash={workflow_hash} existing_hash={existing_hash} profile_key={profile_key}"
            )
            return False
    profiles[workflow_hash] = new_entry
    save_known_good_workflow_profiles(profiles)
    print(f"[comfyapp] marked known-good workflow hash={workflow_hash} changed=1")
    return True


def load_current_dependency_manifest_cache() -> dict:
    """Load the cached current dependency manifest.

    Returns an empty dict when the cache does not exist or is corrupt.
    """
    try:
        if os.path.isfile(CURRENT_CUSTOM_NODE_DEPS_CACHE_PATH):
            with open(CURRENT_CUSTOM_NODE_DEPS_CACHE_PATH, "r") as f:
                data = json.load(f)
            if isinstance(data, dict) and data.get("schema_version") == 1:
                return data
    except (json.JSONDecodeError, OSError):
        pass
    return {}


def save_current_dependency_manifest_cache(cache: dict) -> None:
    """Persist the current dependency manifest cache to volume storage."""
    try:
        os.makedirs(os.path.dirname(CURRENT_CUSTOM_NODE_DEPS_CACHE_PATH), exist_ok=True)
        tmp = f"{CURRENT_CUSTOM_NODE_DEPS_CACHE_PATH}.tmp"
        with open(tmp, "w") as f:
            json.dump(cache, f, indent=2, sort_keys=True)
        os.replace(tmp, CURRENT_CUSTOM_NODE_DEPS_CACHE_PATH)
        _commit_volume_async(label="dependency_manifest_cache")
    except Exception as exc:
        print(f"[comfyapp] failed to save dependency manifest cache: {exc}")


def build_current_custom_node_dependency_manifest_cached() -> dict:
    """Build current dependency manifest using the dependency-only fingerprint cache.

    When the dependency fingerprint is unchanged since the last call, the
    previously-built manifest is returned.  The cache is invalidated only
    when dependency-relevant file content changes (requirements.txt,
    pyproject.toml, setup.py, etc.) GÃ‡Ã¶ ordinary .py source changes do not
    invalidate it.
    """
    source_root = get_runtime_custom_node_source_root_for_dependency_validation()
    dep_fp = custom_node_dependency_fingerprint(source_root)
    dep_hash = dep_fp.get("overall_dependency_hash", "")

    cache = load_current_dependency_manifest_cache()
    cache_manifest = cache.get("manifest") if isinstance(cache, dict) else None
    if (
        cache
        and isinstance(cache_manifest, dict)
        and cache.get("source_root") == source_root
        and cache.get("dependency_fingerprint_hash") == dep_hash
    ):
        print(f"[comfyapp] dependency_manifest_cache hit hash={dep_hash[:16]}...")
        return cache_manifest

    reason = "miss"
    if not cache:
        reason = "no_cache"
    elif cache.get("source_root") != source_root:
        reason = "source_root_changed"
    elif cache.get("dependency_fingerprint_hash") != dep_hash:
        reason = "fingerprint_changed"

    manifest = build_custom_node_dependency_manifest(source_root)
    new_cache = {
        "schema_version": 1,
        "source_root": source_root,
        "dependency_fingerprint_hash": dep_hash,
        "manifest": manifest,
        "created_at": time.time(),
    }
    save_current_dependency_manifest_cache(new_cache)
    print(f"[comfyapp] dependency_manifest_cache miss reason={reason} hash={dep_hash[:16]}...")
    return manifest


_REQ_TOP_LEVEL_NAME = re.compile(r"^[A-Za-z0-9_][A-Za-z0-9_.\-]*")


def _iter_top_level_requirement_names(req_path: str) -> list[str]:
    """Yield top-level distribution names from a requirements.txt.

    Skips comments, blank lines, pip flags (``-r``, ``--editable``), local
    paths (``./foo``), and VCS / URL sources. Extras like ``package[gpu]==1.0``
    are normalised to the base distribution name.
    """
    if not os.path.isfile(req_path):
        return []
    names: list[str] = []
    for raw in Path(req_path).read_text(encoding="utf-8").splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        # Strip inline environment markers
        line = line.split(";", 1)[0].strip()
        if not line:
            continue
        if line.startswith("-r") or line.startswith("--requirement"):
            continue
        if line.startswith("-c") or line.startswith("--constraint"):
            continue
        if line.startswith("-e ") or line.startswith("--editable "):
            line = line.split(" ", 1)[1].strip()
        if line.startswith("./") or line.startswith("../") or line.startswith("/"):
            continue
        if "://" in line:
            continue
        match = _REQ_TOP_LEVEL_NAME.match(line)
        if not match:
            continue
        # Skip packages whose platform marker doesn't match the current platform.
        # This avoids false missing-distribution detection for conditionally-
        # required packages (e.g. triton-windows on Linux, triton on Windows).
        if ";" in raw:
            marker_text = raw.split(";", 1)[1].strip().lower()
            if "sys_platform" in marker_text:
                if "== 'win32'" in marker_text and sys.platform != "win32":
                    continue
                if "== 'linux'" in marker_text and sys.platform != "linux":
                    continue
                if "!= 'win32'" in marker_text and sys.platform == "win32":
                    continue
                if "!= 'linux'" in marker_text and sys.platform == "linux":
                    continue
        names.append(match.group(0))
    return names


def _canonicalize_dist_name(name: str) -> str:
    """Normalize a distribution name per PEP 503 (lowercase, ``[-_.]+`` GÃ¥Ã† ``-``)."""
    return re.sub(r"[-_.]+", "-", name).lower()


def _requirements_have_importable_packages(req_path: str) -> bool:
    """Return True if every top-level requirement listed in ``req_path``
    corresponds to an installed distribution (by metadata ``Name`` field).

    Uses distribution metadata (``importlib.metadata.distributions()``)
    rather than import-module guesses so that packages whose distribution
    name differs from their module name (e.g. ``Pillow`` GÃ¥Ã† ``PIL``,
    ``opencv-python-headless`` GÃ¥Ã† ``cv2``) are correctly recognised.

    Returns ``True`` when the file is empty or contains only local paths /
    VCS sources / pip flags (no top-level packages to verify). Returns
    ``False`` as soon as one named distribution is not found among the
    currently installed packages, indicating the cache entry is stale and
    ``_install_custom_node_requirements`` should reinstall.
    """
    names = _iter_top_level_requirement_names(req_path)
    if not names:
        return True
    import importlib.metadata
    installed = set()
    for dist in importlib.metadata.distributions():
        dist_name = dist.metadata.get("Name")
        if dist_name:
            installed.add(_canonicalize_dist_name(dist_name))
    req_names = {_canonicalize_dist_name(n) for n in names}
    return req_names.issubset(installed)


def model_volume_state(volume_root: str) -> tuple:
    """Snapshot of (folder, name, mtime_ns, size) for every file on a model volume."""
    volume_root = os.path.abspath(volume_root)
    state = []
    for folder in _safe_listdir(volume_root):
        folder_path = os.path.join(volume_root, folder)
        if not os.path.isdir(folder_path):
            continue
        for name in _safe_listdir(folder_path):
            path = os.path.join(folder_path, name)
            if not os.path.isfile(path):
                continue
            try:
                st = os.stat(path)
            except (OSError, FileNotFoundError):
                continue
            state.append((folder, name, st.st_mtime_ns, st.st_size))
    return tuple(state)


def load_runtime_metadata() -> dict:
    """Load JSON metadata from the container filesystem."""
    if not os.path.isfile(RUNTIME_METADATA_PATH):
        return {"requirements": {}, "runtime": {}}
    try:
        with open(RUNTIME_METADATA_PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            return {"requirements": {}, "runtime": {}}
        return data
    except (json.JSONDecodeError, OSError):
        return {"requirements": {}, "runtime": {}}


def save_runtime_metadata(data: dict) -> None:
    """Persist JSON metadata to the volume, scheduling an async commit.

    Skips write when the content is identical to the existing file to
    avoid unnecessary volume commits in the hot path.
    """
    payload = json.dumps(data, indent=2, sort_keys=True)
    if os.path.isfile(RUNTIME_METADATA_PATH):
        try:
            with open(RUNTIME_METADATA_PATH, "r", encoding="utf-8") as f:
                if f.read() == payload:
                    return
        except (OSError, UnicodeDecodeError):
            pass
    os.makedirs(os.path.dirname(RUNTIME_METADATA_PATH), exist_ok=True)
    tmp_path = f"{RUNTIME_METADATA_PATH}.tmp"
    try:
        with open(tmp_path, "w", encoding="utf-8") as f:
            f.write(payload)
        os.replace(tmp_path, RUNTIME_METADATA_PATH)
        _commit_volume_async(label="runtime_metadata")
    except Exception as exc:
        print(f"[comfyapp] failed to save runtime metadata: {exc}")


def set_manager_network_mode_offline() -> list[str]:
    """Force ComfyUI-Manager into offline mode for runtime containers."""
    config_paths = [
        "/root/comfy/ComfyUI/user/default/__manager/config.ini",
        "/root/comfy/ComfyUI/user/default/ComfyUI-Manager/config.ini",
    ]
    written = []
    for config_path in config_paths:
        os.makedirs(os.path.dirname(config_path), exist_ok=True)
        with open(config_path, "w", encoding="utf-8") as f:
            f.write("[default]\nnetwork_mode = offline\n")
        written.append(config_path)
    return written


def _get_system_ram_gb() -> float:
    """Return total system RAM in GB by parsing /proc/meminfo.

    Falls back to 16 GB if the file cannot be read (e.g. non-Linux).
    """
    try:
        with open("/proc/meminfo") as f:
            for line in f:
                if line.startswith("MemTotal:"):
                    kb = int(line.split()[1])
                    val = kb / (1024 * 1024)
                    return round(val, 1)
    except Exception:
        pass
    return 16.0


def load_warmup_profile() -> dict:
    """Return the configured pinned warmup profile, if any.

    Prefers runtime-set env vars over module-level constants so that
    dynamically-set env vars (e.g. restore-time defaults) take effect.
    """
    _get = lambda k, dflt="": (os.environ.get(k) or dflt).strip()
    checkpoint = _get("COMFYMODAL_WARMUP_CHECKPOINT", WARMUP_CHECKPOINT)
    unet = _get("COMFYMODAL_WARMUP_UNET", WARMUP_UNET)
    clip1 = _get("COMFYMODAL_WARMUP_CLIP1", WARMUP_CLIP1)
    clip2 = _get("COMFYMODAL_WARMUP_CLIP2", WARMUP_CLIP2)
    vae = _get("COMFYMODAL_WARMUP_VAE", WARMUP_VAE)
    clip_type = _get("COMFYMODAL_WARMUP_CLIP_TYPE", WARMUP_CLIP_TYPE) or "flux"
    if checkpoint:
        return {
            "mode": "checkpoint",
            "checkpoint": checkpoint,
        }
    if unet and clip1 and clip2 and vae:
        c1, c2 = normalize_flux_clip_pair(clip1, clip2) if clip_type == "flux" else (clip1, clip2)
        return {
            "mode": "split",
            "unet": unet,
            "clip1": c1,
            "clip2": c2,
            "vae": vae,
            "clip_type": clip_type,
        }
    return {}


def extract_requested_model_stack(workflow: dict) -> dict:
    """Extract a minimal model stack from a workflow for warmup matching."""
    stack: dict = {"checkpoint": [], "unet": [], "clip": [], "vae": [], "clip_type": "flux"}
    for node in workflow.values():
        if not isinstance(node, dict):
            continue
        class_type = node.get("class_type", "")
        inputs = node.get("inputs", {})
        if not isinstance(inputs, dict):
            continue
        if class_type in {"CheckpointLoaderSimple", "CheckpointLoader"}:
            value = inputs.get("ckpt_name")
            if isinstance(value, str) and value and value not in stack["checkpoint"]:
                stack["checkpoint"].append(value)
        elif class_type == "UNETLoader":
            value = inputs.get("unet_name")
            if isinstance(value, str) and value and value not in stack["unet"]:
                stack["unet"].append(value)
        elif class_type == "DualCLIPLoader":
            for key in ("clip_name1", "clip_name2"):
                value = inputs.get(key)
                if isinstance(value, str) and value and value not in stack["clip"]:
                    stack["clip"].append(value)
            # Capture clip_type from the actual workflow loader node
            _ct = inputs.get("type", "")
            if isinstance(_ct, str) and _ct:
                stack["clip_type"] = _ct
        elif class_type == "CLIPLoader":
            value = inputs.get("clip_name")
            if isinstance(value, str) and value and value not in stack["clip"]:
                stack["clip"].append(value)
            _ct = inputs.get("type", "")
            if isinstance(_ct, str) and _ct:
                stack["clip_type"] = _ct
        elif class_type == "VAELoader":
            value = inputs.get("vae_name")
            if isinstance(value, str) and value and value not in stack["vae"]:
                stack["vae"].append(value)
    return stack


def warmup_profile_matches_workflow(profile: dict, requested: dict) -> bool:
    """Return True when the requested workflow matches the pinned warmup profile."""
    if not profile:
        return True
    mode = profile.get("mode")
    if mode == "checkpoint":
        checkpoint = profile.get("checkpoint", "")
        return bool(checkpoint) and checkpoint in requested.get("checkpoint", [])
    if mode == "split":
        return (
            profile.get("unet", "") in requested.get("unet", [])
            and profile.get("clip1", "") in requested.get("clip", [])
            and profile.get("clip2", "") in requested.get("clip", [])
            and profile.get("vae", "") in requested.get("vae", [])
        )
    return False


def normalize_flux_clip_pair(clip1: str, clip2: str) -> tuple[str, str]:
    """Return ComfyUI's expected FLUX DualCLIPLoader order: clip-l, then T5.

    Current ComfyUI documents DualCLIPLoader ``type='flux'`` as
    ``clip-l, t5``.  Keep already-correct pairs unchanged, but fix common
    reversed env/profile ordering.
    """
    a = clip1.lower()
    b = clip2.lower()
    a_is_t5 = "t5" in a
    b_is_clip_l = "clip_l" in b or "clip-l" in b or "clip-vit" in b
    if a_is_t5 and b_is_clip_l:
        return clip2, clip1
    return clip1, clip2


def list_sageattention_extension_files(site_packages_root: str) -> list[Path]:
    root = Path(site_packages_root) / "sageattention"
    if not root.is_dir():
        return []
    return sorted(root.glob("*.so"))


def choose_sage_runtime_mode(enabled: bool, extension_files: list[Path], import_ok: bool, smoke_ok: bool) -> tuple[str, str]:
    if not enabled:
        return "disabled", "explicitly-disabled"
    if not extension_files:
        return "triton_fallback", "compiled-extensions-missing"
    if not import_ok:
        return "triton_fallback", "compiled-extensions-unusable"
    if not smoke_ok:
        return "triton_fallback", "smoke-test-failed"
    return "baked_cuda", "compiled-extensions-usable"


def patch_kjnodes_get_sage_func(module, baked_cuda_available: bool) -> bool:
    original = getattr(module, "get_sage_func", None)
    fallback = getattr(module, "attention_pytorch", None)
    wrap_attn_fn = getattr(module, "wrap_attn", None)
    if original is None or fallback is None or wrap_attn_fn is None:
        return False

    module._comfy_modal_baked_cuda_available = baked_cuda_available
    if getattr(module, "_comfy_modal_get_sage_func_patched", False):
        return True

    def wrapped_get_sage_func(sage_attention, allow_compile=False):
        if getattr(module, "_comfy_modal_baked_cuda_available", False) or sage_attention == "disabled":
            return original(sage_attention, allow_compile=allow_compile)
        if sage_attention != "auto" and "sageattn" not in str(sage_attention):
            return original(sage_attention, allow_compile=allow_compile)

        @wrap_attn_fn
        def attention_fallback(q, k, v, heads, mask=None, attn_precision=None, skip_reshape=False, skip_output_reshape=False, **kwargs):
            return fallback(
                q,
                k,
                v,
                heads,
                mask=mask,
                attn_precision=attn_precision,
                skip_reshape=skip_reshape,
                skip_output_reshape=skip_output_reshape,
                **kwargs,
            )

        return attention_fallback

    module.get_sage_func = wrapped_get_sage_func
    module._comfy_modal_get_sage_func_patched = True
    return True


def build_replay_warmup_workflow(workflow: dict) -> dict:
    """Create a lightweight warmup from a real successful workflow.

    This preserves the exact loader nodes, clip order/type, UNET dtype, model
    sampling nodes, custom options, and graph topology that already worked for
    the user.  Only generation cost is reduced: samplers run one step and
    generated latent sizes are capped to 512x512.
    """
    import copy

    def is_numeric(value) -> bool:
        return isinstance(value, (int, float)) or (isinstance(value, str) and value.isdigit())

    warmup = copy.deepcopy(workflow)
    for node in warmup.values():
        if not isinstance(node, dict):
            continue
        class_type = node.get("class_type", "")
        inputs = node.get("inputs", {})
        if not isinstance(inputs, dict):
            continue

        # Reduce common sampler fields across built-in and custom samplers.
        # The previous exact-class check missed custom Flux samplers, causing
        # restore warmup to run full 20/30-step generations.
        for key in ("steps", "num_steps", "total_steps", "sampling_steps"):
            if key in inputs and is_numeric(inputs[key]):
                inputs[key] = 1
        if "start_at_step" in inputs and is_numeric(inputs["start_at_step"]):
            inputs["start_at_step"] = 0
        if "end_at_step" in inputs and is_numeric(inputs["end_at_step"]):
            inputs["end_at_step"] = 1

        # Cap any latent/model dimensions in the replay graph. This is warmup,
        # not final output generation, so smaller tensors preserve model-load
        # benefits without paying full inference cost.
        for key in ("width", "height"):
            if key in inputs and is_numeric(inputs[key]):
                inputs[key] = min(int(inputs[key]), 512)
        if "batch_size" in inputs and is_numeric(inputs["batch_size"]):
            inputs["batch_size"] = min(int(inputs["batch_size"]), 1)
        if class_type == "SaveImage" and "filename_prefix" in inputs:
            inputs["filename_prefix"] = "warmup"
    return warmup


def stack_to_profile(stack: dict) -> dict:
    """Convert an extracted model stack into a warmup-profile-compatible dict.

    The warmup profile uses either "checkpoint" mode (single ckpt_name) or
    "split" mode (individual unet/clip1/clip2/vae).  The stack from
    ``extract_requested_model_stack()`` uses lists; we pick the first
    entry from each list.

    If the stack was saved with a ``clip_type`` key (from the actual
    workflow's loader node), that clip_type is preserved.  Otherwise
    defaults to ``"flux"`` for backward compatibility.
    """
    if stack.get("checkpoint"):
        return {"mode": "checkpoint", "checkpoint": stack["checkpoint"][0]}
    if stack.get("unet") and stack.get("clip") and stack.get("vae"):
        clips = stack["clip"]
        clip1, clip2 = normalize_flux_clip_pair(clips[0], clips[-1] if len(clips) > 1 else clips[0])
        # Preserve clip_type from the actual workflow; fall back to "flux"
        _clip_type = stack.get("clip_type", "flux")
        return {
            "mode": "split",
            "unet": stack["unet"][0],
            "clip1": clip1,
            "clip2": clip2,
            "vae": stack["vae"][0],
            "clip_type": _clip_type,
        }
    return {}


# GÃ¶Ã‡GÃ¶Ã‡ PART 8: Runtime model-download policy GÃ¶Ã‡GÃ¶Ã‡
#   off       GÃ‡Ã¶ Never download model files during request execution.
#   explicit  GÃ‡Ã¶ Only download via explicit preinstall/precache functions.
#   dev       GÃ‡Ã¶ Allow runtime model downloads (current default for dev).
COMFYMODAL_ALLOW_RUNTIME_MODEL_DOWNLOADS = os.getenv("COMFYMODAL_ALLOW_RUNTIME_MODEL_DOWNLOADS", "0") == "1"
COMFYMODAL_MODEL_DOWNLOAD_MODE = os.getenv("COMFYMODAL_MODEL_DOWNLOAD_MODE", "dev").strip().lower()


def _check_runtime_model_download_policy(context: str = "") -> bool:
    """Check whether runtime model downloads are allowed.

    Returns True if downloads are permitted.  Logs a warning if blocked.
    """
    if COMFYMODAL_MODEL_DOWNLOAD_MODE in ("off", "explicit") and not COMFYMODAL_ALLOW_RUNTIME_MODEL_DOWNLOADS:
        context_str = f" ({context})" if context else ""
        print(
            f"[comfyapp] runtime_model_download BLOCKED by policy "
            f"mode={COMFYMODAL_MODEL_DOWNLOAD_MODE}{context_str}"
        )
        return False
    return True


def _verify_model_file(path: str, expected_size: int | None = None, expected_sha256: str | None = None) -> dict:
    """Verify a model file exists and optionally matches size/hash.

    Returns dict with keys: exists, size_ok, sha256_ok, actual_size, actual_sha256.
    """
    result = {"exists": False, "size_ok": None, "sha256_ok": None, "actual_size": None, "actual_sha256": None}
    if not os.path.isfile(path):
        return result
    result["exists"] = True
    try:
        actual_size = os.path.getsize(path)
        result["actual_size"] = actual_size
        if expected_size is not None:
            result["size_ok"] = actual_size == expected_size
    except OSError:
        pass
    if expected_sha256 is not None:
        try:
            actual_sha256 = hashlib.sha256(Path(path).read_bytes()).hexdigest()
            result["actual_sha256"] = actual_sha256
            result["sha256_ok"] = actual_sha256 == expected_sha256
        except OSError:
            pass
    return result


